structured.c_draft:
#include <matrixLIB.h>
#include <builtin_MATH.h>
/* RTDS-style C draft for structured node elimination.
   RAM math reference may use matrix_Add/Sub/Mul on raw arrays.
   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. */
enum { RETAINED_NODES = 4, INTERNAL_NODES = 0 };
/* Dimension names:
 * RETAINED_NODES is the number of external nodes kept in the reduced network.
 * INTERNAL_NODES is the number of eliminated internal nodes used by Schur/Vk recovery.
 */

/* RTDS lifecycle placement for a network with no eliminated internal nodes.
   No Schur complement is required: use the original G matrix and Ihis vector directly. */
STATIC:

    /* Runtime matrix objects */
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double A = 0.0;
    double Gc_1 = 0.0;
    double Z = 0.0;
    /* CODE G scalar aliases */
    double G_n1b_n1b = 0.0;

LOCAL_STATIC:
    /* User RAM-only G symbols */
    double Ga = 0.0;
    double Gb = 0.0;
    double Y = 0.0;

RAM_PASS1:
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * No internal nodes are selected, so fixed RAM G stamping uses the original G matrix.
     * Assign or compute every G-related value before writing g_mat_over.
     * Dynamic entries are registered in GVALUES and refreshed in CODE.
     * ************************************************************************ */



    g_mat_nods[0] = getNodeNum(comp, "n1a");
    g_mat_nods[1] = getNodeNum(comp, "n1b");
    g_mat_nods[2] = getNodeNum(comp, "n2a");
    g_mat_nods[3] = getNodeNum(comp, "N5");
    /* g_mat_over is provided by the PSYS/CBuilder runtime; initialize, do not define it here. */
    for (int row = 0; row < 4; row++) {
        for (int col = 0; col < 4; col++) {
            g_mat_over[row][col] = 0.0;
        }
    }
    g_mat_over[0][0] = Ga;
    g_mat_over[0][1] = -Ga;
    g_mat_over[1][0] = -Ga;
    g_mat_over[1][1] = Ga + Gb + Y;
    g_mat_over[1][2] = -Gb;
    g_mat_over[1][3] = -Y;
    g_mat_over[2][1] = -Gb;
    g_mat_over[2][2] = Gb;
    g_mat_over[3][1] = -Y;
    g_mat_over[3][3] = Y;
    setupGMatrix(4);

    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }

GVALUES:
    /* Dynamic original-G stamp handles, ordered by upper triangle. */
    double varG_n1b_n1b = createGValue("varG_n1b_n1b", "n1b", "n1b", 0, "TRUE");
    double varG_n1b_N5 = createGValue("varG_n1b_N5", "n1b", "N5", 0, "TRUE");
    double varG_N5_N5 = createGValue("varG_N5_N5", "N5", "N5", 0, "TRUE");

CODE:
BEGIN_T0:
    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        rtds_matrix_code_ready = 1;
    }

    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * No internal-node elimination is required.
     * Assign the non-RAM G terms split from the original G matrix directly to GValue handles.
     * No CODE matrix staging is needed because there is no Schur or Vk matrix DAG.
     * ************************************************************************ */



    /* G_n1b_n1b represents G[n1b,n1b]: A*Z + Gc_1. */
    G_n1b_n1b = A*Z + Gc_1;
    varG_n1b_n1b = G_n1b_n1b;
    varG_n1b_N5 = -G_n1b_n1b;
    varG_N5_N5 = G_n1b_n1b;

    /* ************************************************************************
     * CODE-SIDE IHIS VALUE SETUP
     * Update runtime Ihis/history-source values before node-current injection.
     * No internal nodes are eliminated, so assign original Ihis entries directly to Inj.
     * The row order follows the original retained-node order.
     * ************************************************************************ */



    /* Node injection currents follow the retained-node order of the original system. */
    Injn1a = 0.0;
    Injn1b = 0.0;
    Injn2a = 0.0;
    InjN5 = 0.0;

T1_T2:
    /* No internal nodes were eliminated, so there is no Vk recovery step. */

#include <matrixLIB.h>
#include <builtin_MATH.h>
/* RTDS-style C draft for structured node elimination.
   RAM math reference may use matrix_Add/Sub/Mul on raw arrays.
   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. */
enum { RETAINED_NODES = 9, INTERNAL_NODES = 3 };
/* Dimension names:
 * RETAINED_NODES is the number of external nodes kept in the reduced network.
 * INTERNAL_NODES is the number of eliminated internal nodes used by Schur/Vk recovery.
 */

/* RTDS lifecycle placement generated from final-expression dependency analysis.
   RAM_PASS1 stamps only RAM_CONSTANT Gred entries through g_mat_over.
   CODE/BEGIN_T0 computes only dynamic reduced-G and non-direct Ihisred paths.
   T1_T2 reads solved node voltages and recovers eliminated-node voltages when needed. */
STATIC:

    /* Runtime matrix objects */
    MATRIX_ Grr_code = {0};
    MATRIX_ Grk_code = {0};
    MATRIX_ Gkr_code = {0};
    MATRIX_ Gkk_code = {0};
    MATRIX_ Gred_code = {0};
    MATRIX_ Ihisr_code = {0};
    MATRIX_ Ihisk_code = {0};
    MATRIX_ Ihisred_code = {0};
    MATRIX_ Vr_code = {0};
    MATRIX_ Vk_code = {0};
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double AA = 0.0;
    double AN = 0.0;
    double AP = 0.0;
    double BB = 0.0;
    double BN = 0.0;
    double BP = 0.0;
    double CC = 0.0;
    double CN = 0.0;
    double CP = 0.0;
    double G11 = 0.0;
    double G12 = 0.0;
    double G22 = 0.0;
    double G_rc = 0.0;
    double NN = 0.0;
    double PN = 0.0;
    double PP = 0.0;
    double w1 = 0.0;
    double w2 = 0.0;
    /* User Ihis/history symbols */
    double IAhis_rc = 0.0;
    double IBhis_rc = 0.0;
    double IC_his0 = 0.0;
    double IChis_rc = 0.0;
    double Ihis_A = 0.0;
    double Ihis_B = 0.0;
    double Ihis_C = 0.0;
    double Ihis_a = 0.0;
    double Ihis_b = 0.0;
    double Ihis_c = 0.0;
    double Ihis_exclude_c0 = 0.0;
    double Ihis_exclude_c1 = 0.0;
    double Ihis_exclude_c2 = 0.0;
    double Ihis_exclude_c3 = 0.0;
    double Ihis_exclude_c4 = 0.0;
    /* Block-matrix scalar aliases */
    double Gkk_k1_k1 = 0.0;
    double Gkk_k2_k2 = 0.0;
    double Gkk_k3_k3 = 0.0;
    double Gkr_k1_N = 0.0;
    double Gkr_k1_P = 0.0;
    double Gkr_k2_N = 0.0;
    double Gkr_k2_P = 0.0;
    double Gkr_k3_N = 0.0;
    double Gkr_k3_P = 0.0;
    double Gkr_shared_1 = 0.0;
    double Gkr_shared_2 = 0.0;
    double Gkr_shared_3 = 0.0;
    double Gkr_shared_4 = 0.0;
    double Grk_N_k1 = 0.0;
    double Grk_N_k2 = 0.0;
    double Grk_N_k3 = 0.0;
    double Grk_P_k1 = 0.0;
    double Grk_P_k2 = 0.0;
    double Grk_P_k3 = 0.0;
    double Grk_shared_1 = 0.0;
    double Grk_shared_2 = 0.0;
    double Grk_shared_3 = 0.0;
    double Grk_shared_4 = 0.0;
    double Grr_G_G = 0.0;
    double Grr_N_N = 0.0;
    double Grr_P_P = 0.0;
    double Grr_shared_1 = 0.0;
    double Grr_shared_2 = 0.0;
    double Grr_shared_3 = 0.0;
    double Grr_shared_4 = 0.0;
    double W_1_1 = 0.0;
    double W_2_2 = 0.0;
    double W_3_3 = 0.0;

LOCAL_STATIC:
    /* User RAM-only G symbols */
    double gC = 0.0;

RAM_PASS1:
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * Assign or compute every G-related value before any RAM-side use.
     * This section stamps only fixed g_mat_over entries; CODE-owned matrices are refreshed in CODE.
     * ************************************************************************ */



    g_mat_nods[0] = getNodeNum(comp, "P");
    g_mat_nods[1] = getNodeNum(comp, "N");
    /* g_mat_over is provided by the PSYS/CBuilder runtime; initialize, do not define it here. */
    for (int row = 0; row < 2; row++) {
        for (int col = 0; col < 2; col++) {
            g_mat_over[row][col] = 0.0;
        }
    }
    g_mat_over[0][0] = gC;
    g_mat_over[0][1] = -gC;
    g_mat_over[1][0] = -gC;
    g_mat_over[1][1] = gC;
    setupGMatrix(2);

    err += matrixDim(&Grr_code, RETAINED_NODES, RETAINED_NODES);
    err += matrixDim(&Grk_code, RETAINED_NODES, INTERNAL_NODES);
    err += matrixDim(&Gkr_code, INTERNAL_NODES, RETAINED_NODES);
    err += matrixDim(&Gkk_code, INTERNAL_NODES, INTERNAL_NODES);
    err += matrixDim(&Gred_code, RETAINED_NODES, RETAINED_NODES);
    err += matrixDim(&Ihisr_code, RETAINED_NODES, 1);
    err += matrixDim(&Ihisk_code, INTERNAL_NODES, 1);
    err += matrixDim(&Ihisred_code, RETAINED_NODES, 1);
    err += matrixDim(&Vr_code, RETAINED_NODES, 1);
    err += matrixDim(&Vk_code, INTERNAL_NODES, 1);
    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }
    matrix_register(&Grr_code);
    matrix_register(&Grk_code);
    matrix_register(&Gkr_code);
    matrix_register(&Gkk_code);
    matrix_register(&Gred_code);
    matrix_register(&Ihisr_code);
    matrix_register(&Ihisk_code);
    matrix_register(&Ihisred_code);
    matrix_register(&Vr_code);
    matrix_register(&Vk_code);

GVALUES:
    /* Dynamic reduced-G stamp handles, ordered by Gred upper triangle. */
    double varG_A_A = createGValue("varG_A_A", "A", "A", 0, "TRUE");
    double varG_A_B = createGValue("varG_A_B", "A", "B", 0, "TRUE");
    double varG_A_C = createGValue("varG_A_C", "A", "C", 0, "TRUE");
    double varG_A_G = createGValue("varG_A_G", "A", "G", 0, "TRUE");
    double varG_A_RC_a = createGValue("varG_A_RC_a", "A", "RC_a", 0, "TRUE");
    double varG_A_RC_c = createGValue("varG_A_RC_c", "A", "RC_c", 0, "TRUE");
    double varG_A_P = createGValue("varG_A_P", "A", "P", 0, "TRUE");
    double varG_A_N = createGValue("varG_A_N", "A", "N", 0, "TRUE");
    double varG_B_B = createGValue("varG_B_B", "B", "B", 0, "TRUE");
    double varG_B_C = createGValue("varG_B_C", "B", "C", 0, "TRUE");
    double varG_B_G = createGValue("varG_B_G", "B", "G", 0, "TRUE");
    double varG_B_RC_a = createGValue("varG_B_RC_a", "B", "RC_a", 0, "TRUE");
    double varG_B_RC_b = createGValue("varG_B_RC_b", "B", "RC_b", 0, "TRUE");
    double varG_B_P = createGValue("varG_B_P", "B", "P", 0, "TRUE");
    double varG_B_N = createGValue("varG_B_N", "B", "N", 0, "TRUE");
    double varG_C_C = createGValue("varG_C_C", "C", "C", 0, "TRUE");
    double varG_C_G = createGValue("varG_C_G", "C", "G", 0, "TRUE");
    double varG_C_RC_b = createGValue("varG_C_RC_b", "C", "RC_b", 0, "TRUE");
    double varG_C_RC_c = createGValue("varG_C_RC_c", "C", "RC_c", 0, "TRUE");
    double varG_C_P = createGValue("varG_C_P", "C", "P", 0, "TRUE");
    double varG_C_N = createGValue("varG_C_N", "C", "N", 0, "TRUE");
    double varG_G_G = createGValue("varG_G_G", "G", "G", 0, "TRUE");
    double varG_G_RC_a = createGValue("varG_G_RC_a", "G", "RC_a", 0, "TRUE");
    double varG_G_RC_b = createGValue("varG_G_RC_b", "G", "RC_b", 0, "TRUE");
    double varG_G_RC_c = createGValue("varG_G_RC_c", "G", "RC_c", 0, "TRUE");
    double varG_G_P = createGValue("varG_G_P", "G", "P", 0, "TRUE");
    double varG_G_N = createGValue("varG_G_N", "G", "N", 0, "TRUE");
    double varG_RC_a_RC_a = createGValue("varG_RC_a_RC_a", "RC_a", "RC_a", 0, "TRUE");
    double varG_RC_a_P = createGValue("varG_RC_a_P", "RC_a", "P", 0, "TRUE");
    double varG_RC_a_N = createGValue("varG_RC_a_N", "RC_a", "N", 0, "TRUE");
    double varG_RC_b_RC_b = createGValue("varG_RC_b_RC_b", "RC_b", "RC_b", 0, "TRUE");
    double varG_RC_b_P = createGValue("varG_RC_b_P", "RC_b", "P", 0, "TRUE");
    double varG_RC_b_N = createGValue("varG_RC_b_N", "RC_b", "N", 0, "TRUE");
    double varG_RC_c_RC_c = createGValue("varG_RC_c_RC_c", "RC_c", "RC_c", 0, "TRUE");
    double varG_RC_c_P = createGValue("varG_RC_c_P", "RC_c", "P", 0, "TRUE");
    double varG_RC_c_N = createGValue("varG_RC_c_N", "RC_c", "N", 0, "TRUE");
    double varG_P_P = createGValue("varG_P_P", "P", "P", 0, "TRUE");
    double varG_P_N = createGValue("varG_P_N", "P", "N", 0, "TRUE");
    double varG_N_N = createGValue("varG_N_N", "N", "N", 0, "TRUE");

CODE:
BEGIN_T0:
    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        conditionMatrixForCODE(&Grr_code);
        conditionMatrixForCODE(&Grk_code);
        conditionMatrixForCODE(&Gkr_code);
        conditionMatrixForCODE(&Gkk_code);
        conditionMatrixForCODE(&Gred_code);
        conditionMatrixForCODE(&Ihisr_code);
        conditionMatrixForCODE(&Ihisk_code);
        conditionMatrixForCODE(&Ihisred_code);
        conditionMatrixForCODE(&Vr_code);
        conditionMatrixForCODE(&Vk_code);
        rtds_matrix_code_ready = 1;
    }


    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * Update runtime G-related symbols and matrices before the reduction math below.
     * Only matrices required by dynamic G, Ihis reduction, or Vk recovery are refreshed.
     * ************************************************************************ */



    /* Runtime refresh. Use set_CODE for matrices touched in CODE; do not write MATRIX_.p directly. */
    /* Grr_shared_1 represents Grr[A,A], Grr[B,B], Grr[C,C]: 2.0*G11 + 2.0*w1. */
    Grr_shared_1 = 2.0*G11 + 2.0*w1;
    /* Grr_shared_2 represents Grr[A,B], Grr[A,C], Grr[B,A], Grr[B,C], Grr[C,A], Grr[C,B]: -G11 - w1. */
    Grr_shared_2 = -G11 - w1;
    /* Grr_G_G represents Grr[G,G]: 3.0*G22 + 3.0*w2. */
    Grr_G_G = 3.0*G22 + 3.0*w2;
    /* Grr_shared_3 represents Grr[RC_a,RC_a], Grr[RC_b,RC_b], Grr[RC_c,RC_c]: G_rc. */
    Grr_shared_3 = G_rc;
    /* Grr_P_P represents Grr[P,P]: PP. */
    Grr_P_P = PP;
    /* Grr_shared_4 represents Grr[P,N], Grr[N,P]: PN. */
    Grr_shared_4 = PN;
    /* Grr_N_N represents Grr[N,N]: NN. */
    Grr_N_N = NN;
    /* Grk_shared_1 represents Grk[A,k1], Grk[B,k2], Grk[C,k3]: G12. */
    Grk_shared_1 = G12;
    /* Grk_shared_2 represents Grk[A,k3], Grk[B,k1], Grk[C,k2]: -G12. */
    Grk_shared_2 = -G12;
    /* Grk_shared_3 represents Grk[G,k1], Grk[G,k2], Grk[G,k3]: -G22 - w2. */
    Grk_shared_3 = -G22 - w2;
    /* Grk_shared_4 represents Grk[RC_a,k1], Grk[RC_b,k2], Grk[RC_c,k3]: -G_rc. */
    Grk_shared_4 = -G_rc;
    /* Grk_P_k1 represents Grk[P,k1]: AP. */
    Grk_P_k1 = AP;
    /* Grk_P_k2 represents Grk[P,k2]: BP. */
    Grk_P_k2 = BP;
    /* Grk_P_k3 represents Grk[P,k3]: CP. */
    Grk_P_k3 = CP;
    /* Grk_N_k1 represents Grk[N,k1]: AN. */
    Grk_N_k1 = AN;
    /* Grk_N_k2 represents Grk[N,k2]: BN. */
    Grk_N_k2 = BN;
    /* Grk_N_k3 represents Grk[N,k3]: CN. */
    Grk_N_k3 = CN;
    /* Gkr_shared_1 represents Gkr[k1,A], Gkr[k2,B], Gkr[k3,C]: G12. */
    Gkr_shared_1 = G12;
    /* Gkr_shared_2 represents Gkr[k1,B], Gkr[k2,C], Gkr[k3,A]: -G12. */
    Gkr_shared_2 = -G12;
    /* Gkr_shared_3 represents Gkr[k1,G], Gkr[k2,G], Gkr[k3,G]: -G22 - w2. */
    Gkr_shared_3 = -G22 - w2;
    /* Gkr_shared_4 represents Gkr[k1,RC_a], Gkr[k2,RC_b], Gkr[k3,RC_c]: -G_rc. */
    Gkr_shared_4 = -G_rc;
    /* Gkr_k1_P represents Gkr[k1,P]: AP. */
    Gkr_k1_P = AP;
    /* Gkr_k1_N represents Gkr[k1,N]: AN. */
    Gkr_k1_N = AN;
    /* Gkr_k2_P represents Gkr[k2,P]: BP. */
    Gkr_k2_P = BP;
    /* Gkr_k2_N represents Gkr[k2,N]: BN. */
    Gkr_k2_N = BN;
    /* Gkr_k3_P represents Gkr[k3,P]: CP. */
    Gkr_k3_P = CP;
    /* Gkr_k3_N represents Gkr[k3,N]: CN. */
    Gkr_k3_N = CN;
    /* Gkk_k1_k1 represents Gkk[k1,k1]: AA + G22 + G_rc + w2. */
    Gkk_k1_k1 = AA + G22 + G_rc + w2;
    /* Gkk_k2_k2 represents Gkk[k2,k2]: BB + G22 + G_rc + w2. */
    Gkk_k2_k2 = BB + G22 + G_rc + w2;
    /* Gkk_k3_k3 represents Gkk[k3,k3]: CC + G22 + G_rc + w2. */
    Gkk_k3_k3 = CC + G22 + G_rc + w2;
    /* W_1_1 represents W[1,1]: 1.0/(AA + G22 + G_rc + w2). */
    W_1_1 = 1.0/(AA + G22 + G_rc + w2);
    /* W_2_2 represents W[2,2]: 1.0/(BB + G22 + G_rc + w2). */
    W_2_2 = 1.0/(BB + G22 + G_rc + w2);
    /* W_3_3 represents W[3,3]: 1.0/(CC + G22 + G_rc + w2). */
    W_3_3 = 1.0/(CC + G22 + G_rc + w2);
    set_CODE(&Grr_code, 0, 0, Grr_shared_1);
    set_CODE(&Grr_code, 1, 1, Grr_shared_1);
    set_CODE(&Grr_code, 2, 2, Grr_shared_1);
    set_CODE(&Grr_code, 0, 1, Grr_shared_2);
    set_CODE(&Grr_code, 0, 2, Grr_shared_2);
    set_CODE(&Grr_code, 1, 0, Grr_shared_2);
    set_CODE(&Grr_code, 1, 2, Grr_shared_2);
    set_CODE(&Grr_code, 2, 0, Grr_shared_2);
    set_CODE(&Grr_code, 2, 1, Grr_shared_2);
    set_CODE(&Grr_code, 3, 3, Grr_G_G);
    set_CODE(&Grr_code, 4, 4, Grr_shared_3);
    set_CODE(&Grr_code, 5, 5, Grr_shared_3);
    set_CODE(&Grr_code, 6, 6, Grr_shared_3);
    set_CODE(&Grr_code, 7, 7, Grr_P_P);
    set_CODE(&Grr_code, 7, 8, Grr_shared_4);
    set_CODE(&Grr_code, 8, 7, Grr_shared_4);
    set_CODE(&Grr_code, 8, 8, Grr_N_N);
    set_CODE(&Grk_code, 0, 0, Grk_shared_1);
    set_CODE(&Grk_code, 1, 1, Grk_shared_1);
    set_CODE(&Grk_code, 2, 2, Grk_shared_1);
    set_CODE(&Grk_code, 0, 2, Grk_shared_2);
    set_CODE(&Grk_code, 1, 0, Grk_shared_2);
    set_CODE(&Grk_code, 2, 1, Grk_shared_2);
    set_CODE(&Grk_code, 3, 0, Grk_shared_3);
    set_CODE(&Grk_code, 3, 1, Grk_shared_3);
    set_CODE(&Grk_code, 3, 2, Grk_shared_3);
    set_CODE(&Grk_code, 4, 0, Grk_shared_4);
    set_CODE(&Grk_code, 5, 1, Grk_shared_4);
    set_CODE(&Grk_code, 6, 2, Grk_shared_4);
    set_CODE(&Grk_code, 7, 0, Grk_P_k1);
    set_CODE(&Grk_code, 7, 1, Grk_P_k2);
    set_CODE(&Grk_code, 7, 2, Grk_P_k3);
    set_CODE(&Grk_code, 8, 0, Grk_N_k1);
    set_CODE(&Grk_code, 8, 1, Grk_N_k2);
    set_CODE(&Grk_code, 8, 2, Grk_N_k3);
    set_CODE(&Gkr_code, 0, 0, Gkr_shared_1);
    set_CODE(&Gkr_code, 1, 1, Gkr_shared_1);
    set_CODE(&Gkr_code, 2, 2, Gkr_shared_1);
    set_CODE(&Gkr_code, 0, 1, Gkr_shared_2);
    set_CODE(&Gkr_code, 1, 2, Gkr_shared_2);
    set_CODE(&Gkr_code, 2, 0, Gkr_shared_2);
    set_CODE(&Gkr_code, 0, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 1, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 2, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 0, 4, Gkr_shared_4);
    set_CODE(&Gkr_code, 1, 5, Gkr_shared_4);
    set_CODE(&Gkr_code, 2, 6, Gkr_shared_4);
    set_CODE(&Gkr_code, 0, 7, Gkr_k1_P);
    set_CODE(&Gkr_code, 0, 8, Gkr_k1_N);
    set_CODE(&Gkr_code, 1, 7, Gkr_k2_P);
    set_CODE(&Gkr_code, 1, 8, Gkr_k2_N);
    set_CODE(&Gkr_code, 2, 7, Gkr_k3_P);
    set_CODE(&Gkr_code, 2, 8, Gkr_k3_N);
    set_CODE(&Gkk_code, 0, 0, Gkk_k1_k1);
    set_CODE(&Gkk_code, 1, 1, Gkk_k2_k2);
    set_CODE(&Gkk_code, 2, 2, Gkk_k3_k3);

    /* ************************************************************************
     * CODE-SIDE IHIS VALUE SETUP
     * Update runtime Ihis/history-source values before per-step injection math.
     * Only non-direct Ihisred rows are computed through MATRIX_ CODE helpers.
     * ************************************************************************ */



    set_CODE(&Ihisr_code, 0, 0, Ihis_A - Ihis_C);
    set_CODE(&Ihisr_code, 1, 0, -Ihis_A + Ihis_B);
    set_CODE(&Ihisr_code, 2, 0, -Ihis_B + Ihis_C);
    set_CODE(&Ihisr_code, 3, 0, -Ihis_a - Ihis_b - Ihis_c);
    set_CODE(&Ihisr_code, 4, 0, -IAhis_rc);
    set_CODE(&Ihisr_code, 5, 0, -IBhis_rc);
    set_CODE(&Ihisr_code, 6, 0, -IChis_rc);
    set_CODE(&Ihisr_code, 7, 0, Ihis_exclude_c3);
    set_CODE(&Ihisr_code, 8, 0, Ihis_exclude_c4);
    set_CODE(&Ihisk_code, 0, 0, IAhis_rc + Ihis_a + Ihis_exclude_c0);
    set_CODE(&Ihisk_code, 1, 0, IBhis_rc + Ihis_b + Ihis_exclude_c1);
    set_CODE(&Ihisk_code, 2, 0, IChis_rc + Ihis_c + Ihis_exclude_c2);

    /* Sliced Schur sparse updates for dynamic Gred entries.
       Each assignment uses Gred[i,j] = Grr[i,j] - Grk[i,k] * W * Gkr[k,j]. */
    /* Stamp dynamic Gred entries directly from the sliced dynamic block. */
    /* varG_A_A represents Gred[A,A]: Grr_shared_1 - Grk_shared_1*W_1_1*Gkr_shared_1 - Grk_shared_2*W_3_3*Gkr_shared_2. */
    /* Gred[A,A] = Grr[A,A] - Grk[A,k] * W * Gkr[k,A]. */
    varG_A_A = Grr_shared_1 - Grk_shared_1*W_1_1*Gkr_shared_1 - Grk_shared_2*W_3_3*Gkr_shared_2;
    /* varG_A_B represents Gred[A,B]: Grr_shared_2 - Grk_shared_1*W_1_1*Gkr_shared_2. */
    /* Gred[A,B] = Grr[A,B] - Grk[A,k] * W * Gkr[k,B]. */
    varG_A_B = Grr_shared_2 - Grk_shared_1*W_1_1*Gkr_shared_2;
    /* varG_A_C represents Gred[A,C]: Grr_shared_2 - Grk_shared_2*W_3_3*Gkr_shared_1. */
    /* Gred[A,C] = Grr[A,C] - Grk[A,k] * W * Gkr[k,C]. */
    varG_A_C = Grr_shared_2 - Grk_shared_2*W_3_3*Gkr_shared_1;
    /* varG_A_G represents Gred[A,G]: -Grk_shared_1*W_1_1*Gkr_shared_3 - Grk_shared_2*W_3_3*Gkr_shared_3. */
    /* Gred[A,G] = Grr[A,G] - Grk[A,k] * W * Gkr[k,G]. */
    varG_A_G = -Grk_shared_1*W_1_1*Gkr_shared_3 - Grk_shared_2*W_3_3*Gkr_shared_3;
    /* varG_A_RC_a represents Gred[A,RC_a]: -Grk_shared_1*W_1_1*Gkr_shared_4. */
    /* Gred[A,RC_a] = Grr[A,RC_a] - Grk[A,k] * W * Gkr[k,RC_a]. */
    varG_A_RC_a = -Grk_shared_1*W_1_1*Gkr_shared_4;
    /* varG_A_RC_c represents Gred[A,RC_c]: -Grk_shared_2*W_3_3*Gkr_shared_4. */
    /* Gred[A,RC_c] = Grr[A,RC_c] - Grk[A,k] * W * Gkr[k,RC_c]. */
    varG_A_RC_c = -Grk_shared_2*W_3_3*Gkr_shared_4;
    /* varG_A_P represents Gred[A,P]: -Grk_shared_1*W_1_1*Gkr_k1_P - Grk_shared_2*W_3_3*Gkr_k3_P. */
    /* Gred[A,P] = Grr[A,P] - Grk[A,k] * W * Gkr[k,P]. */
    varG_A_P = -Grk_shared_1*W_1_1*Gkr_k1_P - Grk_shared_2*W_3_3*Gkr_k3_P;
    /* varG_A_N represents Gred[A,N]: -Grk_shared_1*W_1_1*Gkr_k1_N - Grk_shared_2*W_3_3*Gkr_k3_N. */
    /* Gred[A,N] = Grr[A,N] - Grk[A,k] * W * Gkr[k,N]. */
    varG_A_N = -Grk_shared_1*W_1_1*Gkr_k1_N - Grk_shared_2*W_3_3*Gkr_k3_N;
    /* varG_B_B represents Gred[B,B]: Grr_shared_1 - Grk_shared_2*W_1_1*Gkr_shared_2 - Grk_shared_1*W_2_2*Gkr_shared_1. */
    /* Gred[B,B] = Grr[B,B] - Grk[B,k] * W * Gkr[k,B]. */
    varG_B_B = Grr_shared_1 - Grk_shared_2*W_1_1*Gkr_shared_2 - Grk_shared_1*W_2_2*Gkr_shared_1;
    /* varG_B_C represents Gred[B,C]: Grr_shared_2 - Grk_shared_1*W_2_2*Gkr_shared_2. */
    /* Gred[B,C] = Grr[B,C] - Grk[B,k] * W * Gkr[k,C]. */
    varG_B_C = Grr_shared_2 - Grk_shared_1*W_2_2*Gkr_shared_2;
    /* varG_B_G represents Gred[B,G]: -Grk_shared_2*W_1_1*Gkr_shared_3 - Grk_shared_1*W_2_2*Gkr_shared_3. */
    /* Gred[B,G] = Grr[B,G] - Grk[B,k] * W * Gkr[k,G]. */
    varG_B_G = -Grk_shared_2*W_1_1*Gkr_shared_3 - Grk_shared_1*W_2_2*Gkr_shared_3;
    /* varG_B_RC_a reuses Gred[B,RC_a]: -varG_A_RC_a. */
    varG_B_RC_a = -varG_A_RC_a;
    /* varG_B_RC_b represents Gred[B,RC_b]: -Grk_shared_1*W_2_2*Gkr_shared_4. */
    /* Gred[B,RC_b] = Grr[B,RC_b] - Grk[B,k] * W * Gkr[k,RC_b]. */
    varG_B_RC_b = -Grk_shared_1*W_2_2*Gkr_shared_4;
    /* varG_B_P represents Gred[B,P]: -Grk_shared_2*W_1_1*Gkr_k1_P - Grk_shared_1*W_2_2*Gkr_k2_P. */
    /* Gred[B,P] = Grr[B,P] - Grk[B,k] * W * Gkr[k,P]. */
    varG_B_P = -Grk_shared_2*W_1_1*Gkr_k1_P - Grk_shared_1*W_2_2*Gkr_k2_P;
    /* varG_B_N represents Gred[B,N]: -Grk_shared_2*W_1_1*Gkr_k1_N - Grk_shared_1*W_2_2*Gkr_k2_N. */
    /* Gred[B,N] = Grr[B,N] - Grk[B,k] * W * Gkr[k,N]. */
    varG_B_N = -Grk_shared_2*W_1_1*Gkr_k1_N - Grk_shared_1*W_2_2*Gkr_k2_N;
    /* varG_C_C represents Gred[C,C]: Grr_shared_1 - Grk_shared_2*W_2_2*Gkr_shared_2 - Grk_shared_1*W_3_3*Gkr_shared_1. */
    /* Gred[C,C] = Grr[C,C] - Grk[C,k] * W * Gkr[k,C]. */
    varG_C_C = Grr_shared_1 - Grk_shared_2*W_2_2*Gkr_shared_2 - Grk_shared_1*W_3_3*Gkr_shared_1;
    /* varG_C_G represents Gred[C,G]: -Grk_shared_2*W_2_2*Gkr_shared_3 - Grk_shared_1*W_3_3*Gkr_shared_3. */
    /* Gred[C,G] = Grr[C,G] - Grk[C,k] * W * Gkr[k,G]. */
    varG_C_G = -Grk_shared_2*W_2_2*Gkr_shared_3 - Grk_shared_1*W_3_3*Gkr_shared_3;
    /* varG_C_RC_b reuses Gred[C,RC_b]: -varG_B_RC_b. */
    varG_C_RC_b = -varG_B_RC_b;
    /* varG_C_RC_c reuses Gred[C,RC_c]: -varG_A_RC_c. */
    varG_C_RC_c = -varG_A_RC_c;
    /* varG_C_P represents Gred[C,P]: -Grk_shared_2*W_2_2*Gkr_k2_P - Grk_shared_1*W_3_3*Gkr_k3_P. */
    /* Gred[C,P] = Grr[C,P] - Grk[C,k] * W * Gkr[k,P]. */
    varG_C_P = -Grk_shared_2*W_2_2*Gkr_k2_P - Grk_shared_1*W_3_3*Gkr_k3_P;
    /* varG_C_N represents Gred[C,N]: -Grk_shared_2*W_2_2*Gkr_k2_N - Grk_shared_1*W_3_3*Gkr_k3_N. */
    /* Gred[C,N] = Grr[C,N] - Grk[C,k] * W * Gkr[k,N]. */
    varG_C_N = -Grk_shared_2*W_2_2*Gkr_k2_N - Grk_shared_1*W_3_3*Gkr_k3_N;
    /* varG_G_G represents Gred[G,G]: Grr_G_G - Grk_shared_3*W_1_1*Gkr_shared_3 - Grk_shared_3*W_2_2*Gkr_shared_3 - Grk_shared_3*W_3_3*Gkr_shared_3. */
    /* Gred[G,G] = Grr[G,G] - Grk[G,k] * W * Gkr[k,G]. */
    varG_G_G = Grr_G_G - Grk_shared_3*W_1_1*Gkr_shared_3 - Grk_shared_3*W_2_2*Gkr_shared_3 - Grk_shared_3*W_3_3*Gkr_shared_3;
    /* varG_G_RC_a represents Gred[G,RC_a]: -Grk_shared_3*W_1_1*Gkr_shared_4. */
    /* Gred[G,RC_a] = Grr[G,RC_a] - Grk[G,k] * W * Gkr[k,RC_a]. */
    varG_G_RC_a = -Grk_shared_3*W_1_1*Gkr_shared_4;
    /* varG_G_RC_b represents Gred[G,RC_b]: -Grk_shared_3*W_2_2*Gkr_shared_4. */
    /* Gred[G,RC_b] = Grr[G,RC_b] - Grk[G,k] * W * Gkr[k,RC_b]. */
    varG_G_RC_b = -Grk_shared_3*W_2_2*Gkr_shared_4;
    /* varG_G_RC_c represents Gred[G,RC_c]: -Grk_shared_3*W_3_3*Gkr_shared_4. */
    /* Gred[G,RC_c] = Grr[G,RC_c] - Grk[G,k] * W * Gkr[k,RC_c]. */
    varG_G_RC_c = -Grk_shared_3*W_3_3*Gkr_shared_4;
    /* varG_G_P represents Gred[G,P]: -Grk_shared_3*W_1_1*Gkr_k1_P - Grk_shared_3*W_2_2*Gkr_k2_P - Grk_shared_3*W_3_3*Gkr_k3_P. */
    /* Gred[G,P] = Grr[G,P] - Grk[G,k] * W * Gkr[k,P]. */
    varG_G_P = -Grk_shared_3*W_1_1*Gkr_k1_P - Grk_shared_3*W_2_2*Gkr_k2_P - Grk_shared_3*W_3_3*Gkr_k3_P;
    /* varG_G_N represents Gred[G,N]: -Grk_shared_3*W_1_1*Gkr_k1_N - Grk_shared_3*W_2_2*Gkr_k2_N - Grk_shared_3*W_3_3*Gkr_k3_N. */
    /* Gred[G,N] = Grr[G,N] - Grk[G,k] * W * Gkr[k,N]. */
    varG_G_N = -Grk_shared_3*W_1_1*Gkr_k1_N - Grk_shared_3*W_2_2*Gkr_k2_N - Grk_shared_3*W_3_3*Gkr_k3_N;
    /* varG_RC_a_RC_a represents Gred[RC_a,RC_a]: Grr_shared_3 - Grk_shared_4*W_1_1*Gkr_shared_4. */
    /* Gred[RC_a,RC_a] = Grr[RC_a,RC_a] - Grk[RC_a,k] * W * Gkr[k,RC_a]. */
    varG_RC_a_RC_a = Grr_shared_3 - Grk_shared_4*W_1_1*Gkr_shared_4;
    /* varG_RC_a_P represents Gred[RC_a,P]: -Grk_shared_4*W_1_1*Gkr_k1_P. */
    /* Gred[RC_a,P] = Grr[RC_a,P] - Grk[RC_a,k] * W * Gkr[k,P]. */
    varG_RC_a_P = -Grk_shared_4*W_1_1*Gkr_k1_P;
    /* varG_RC_a_N represents Gred[RC_a,N]: -Grk_shared_4*W_1_1*Gkr_k1_N. */
    /* Gred[RC_a,N] = Grr[RC_a,N] - Grk[RC_a,k] * W * Gkr[k,N]. */
    varG_RC_a_N = -Grk_shared_4*W_1_1*Gkr_k1_N;
    /* varG_RC_b_RC_b represents Gred[RC_b,RC_b]: Grr_shared_3 - Grk_shared_4*W_2_2*Gkr_shared_4. */
    /* Gred[RC_b,RC_b] = Grr[RC_b,RC_b] - Grk[RC_b,k] * W * Gkr[k,RC_b]. */
    varG_RC_b_RC_b = Grr_shared_3 - Grk_shared_4*W_2_2*Gkr_shared_4;
    /* varG_RC_b_P represents Gred[RC_b,P]: -Grk_shared_4*W_2_2*Gkr_k2_P. */
    /* Gred[RC_b,P] = Grr[RC_b,P] - Grk[RC_b,k] * W * Gkr[k,P]. */
    varG_RC_b_P = -Grk_shared_4*W_2_2*Gkr_k2_P;
    /* varG_RC_b_N represents Gred[RC_b,N]: -Grk_shared_4*W_2_2*Gkr_k2_N. */
    /* Gred[RC_b,N] = Grr[RC_b,N] - Grk[RC_b,k] * W * Gkr[k,N]. */
    varG_RC_b_N = -Grk_shared_4*W_2_2*Gkr_k2_N;
    /* varG_RC_c_RC_c represents Gred[RC_c,RC_c]: Grr_shared_3 - Grk_shared_4*W_3_3*Gkr_shared_4. */
    /* Gred[RC_c,RC_c] = Grr[RC_c,RC_c] - Grk[RC_c,k] * W * Gkr[k,RC_c]. */
    varG_RC_c_RC_c = Grr_shared_3 - Grk_shared_4*W_3_3*Gkr_shared_4;
    /* varG_RC_c_P represents Gred[RC_c,P]: -Grk_shared_4*W_3_3*Gkr_k3_P. */
    /* Gred[RC_c,P] = Grr[RC_c,P] - Grk[RC_c,k] * W * Gkr[k,P]. */
    varG_RC_c_P = -Grk_shared_4*W_3_3*Gkr_k3_P;
    /* varG_RC_c_N represents Gred[RC_c,N]: -Grk_shared_4*W_3_3*Gkr_k3_N. */
    /* Gred[RC_c,N] = Grr[RC_c,N] - Grk[RC_c,k] * W * Gkr[k,N]. */
    varG_RC_c_N = -Grk_shared_4*W_3_3*Gkr_k3_N;
    /* varG_P_P represents Gred[P,P]: Grr_P_P - Grk_P_k1*W_1_1*Gkr_k1_P - Grk_P_k2*W_2_2*Gkr_k2_P - Grk_P_k3*W_3_3*Gkr_k3_P. */
    /* Gred[P,P] = Grr[P,P] - Grk[P,k] * W * Gkr[k,P]. */
    varG_P_P = Grr_P_P - Grk_P_k1*W_1_1*Gkr_k1_P - Grk_P_k2*W_2_2*Gkr_k2_P - Grk_P_k3*W_3_3*Gkr_k3_P;
    /* varG_P_N represents Gred[P,N]: Grr_shared_4 - Grk_P_k1*W_1_1*Gkr_k1_N - Grk_P_k2*W_2_2*Gkr_k2_N - Grk_P_k3*W_3_3*Gkr_k3_N. */
    /* Gred[P,N] = Grr[P,N] - Grk[P,k] * W * Gkr[k,N]. */
    varG_P_N = Grr_shared_4 - Grk_P_k1*W_1_1*Gkr_k1_N - Grk_P_k2*W_2_2*Gkr_k2_N - Grk_P_k3*W_3_3*Gkr_k3_N;
    /* varG_N_N represents Gred[N,N]: Grr_N_N - Grk_N_k1*W_1_1*Gkr_k1_N - Grk_N_k2*W_2_2*Gkr_k2_N - Grk_N_k3*W_3_3*Gkr_k3_N. */
    /* Gred[N,N] = Grr[N,N] - Grk[N,k] * W * Gkr[k,N]. */
    varG_N_N = Grr_N_N - Grk_N_k1*W_1_1*Gkr_k1_N - Grk_N_k2*W_2_2*Gkr_k2_N - Grk_N_k3*W_3_3*Gkr_k3_N;

    /* Ihisred is a per-step injection vector: Ihisred = Ihisr - Grk * W * Ihisk. */
    /* Diagonal Gkk scalar CODE path: Ihisred = Ihisr - sum_k Grk[i,k] * Ihisk[k] / Gkk[k,k]. */
    {
        double inv_gkk_diag[INTERNAL_NODES];
        for (int k = 0; k < INTERNAL_NODES; k++) {
            inv_gkk_diag[k] = 1.0 / get_CODE(&Gkk_code, k, k);
        }
        for (int i = 0; i < RETAINED_NODES; i++) {
            double ihis = get_CODE(&Ihisr_code, i, 0);
            for (int k = 0; k < INTERNAL_NODES; k++) {
                ihis -= get_CODE(&Grk_code, i, k) * get_CODE(&Ihisk_code, k, 0) * inv_gkk_diag[k];
            }
            set_CODE(&Ihisred_code, i, 0, ihis);
        }
    }
    set_CODE(&Ihisred_code, 7, 0, get_CODE(&Ihisred_code, 7, 0) + IC_his0);
    set_CODE(&Ihisred_code, 8, 0, get_CODE(&Ihisred_code, 8, 0) + -IC_his0);
    /* Node injection currents follow the retained-node order of the reduced system. */
    InjA = get_CODE(&Ihisred_code, 0, 0);
    InjB = get_CODE(&Ihisred_code, 1, 0);
    InjC = get_CODE(&Ihisred_code, 2, 0);
    InjG = get_CODE(&Ihisred_code, 3, 0);
    InjRC_a = get_CODE(&Ihisred_code, 4, 0);
    InjRC_b = get_CODE(&Ihisred_code, 5, 0);
    InjRC_c = get_CODE(&Ihisred_code, 6, 0);
    InjP = get_CODE(&Ihisred_code, 7, 0);
    InjN = get_CODE(&Ihisred_code, 8, 0);

T1_T2:
    /* Internal-node voltage recovery after solved retained-node voltages are available. */
    set_CODE(&Vr_code, 0, 0, A);
    set_CODE(&Vr_code, 1, 0, B);
    set_CODE(&Vr_code, 2, 0, C);
    set_CODE(&Vr_code, 3, 0, G);
    set_CODE(&Vr_code, 4, 0, RC_a);
    set_CODE(&Vr_code, 5, 0, RC_b);
    set_CODE(&Vr_code, 6, 0, RC_c);
    set_CODE(&Vr_code, 7, 0, P);
    set_CODE(&Vr_code, 8, 0, N);
    /* Diagonal Gkk scalar CODE path: Vk[k] = -(Gkr[k,*] * Vr + Ihisk[k]) / Gkk[k,k]. */
    {
        double inv_gkk_diag[INTERNAL_NODES];
        for (int k = 0; k < INTERNAL_NODES; k++) {
            inv_gkk_diag[k] = 1.0 / get_CODE(&Gkk_code, k, k);
        }
        for (int k = 0; k < INTERNAL_NODES; k++) {
            double vk_sum = 0.0;
            for (int j = 0; j < RETAINED_NODES; j++) {
                vk_sum += get_CODE(&Gkr_code, k, j) * get_CODE(&Vr_code, j, 0);
            }
            vk_sum += get_CODE(&Ihisk_code, k, 0);
            set_CODE(&Vk_code, k, 0, -vk_sum * inv_gkk_diag[k]);
        }
    }

    /* One variable per eliminated node, in effective k order. */
    x = get_CODE(&Vk_code, 0, 0);
    y = get_CODE(&Vk_code, 1, 0);
    z = get_CODE(&Vk_code, 2, 0);

#include <matrixLIB.h>
#include <builtin_MATH.h>
/* RTDS-style C draft for structured node elimination.
   RAM math reference may use matrix_Add/Sub/Mul on raw arrays.
   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. */
enum { RETAINED_NODES = 9, INTERNAL_NODES = 3 };
/* Dimension names:
 * RETAINED_NODES is the number of external nodes kept in the reduced network.
 * INTERNAL_NODES is the number of eliminated internal nodes used by Schur/Vk recovery.
 */

/* RTDS lifecycle placement generated from final-expression dependency analysis.
   RAM_PASS1 stamps only RAM_CONSTANT Gred entries through g_mat_over.
   CODE/BEGIN_T0 computes only dynamic reduced-G and non-direct Ihisred paths.
   T1_T2 reads solved node voltages and recovers eliminated-node voltages when needed. */
STATIC:

    /* Runtime matrix objects */
    MATRIX_ Grr_code = {0};
    MATRIX_ Grk_code = {0};
    MATRIX_ Gkr_code = {0};
    MATRIX_ Gkk_code = {0};
    MATRIX_ Gred_code = {0};
    MATRIX_ Ihisr_code = {0};
    MATRIX_ Ihisk_code = {0};
    MATRIX_ Ihisred_code = {0};
    MATRIX_ Vr_code = {0};
    MATRIX_ Vk_code = {0};
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double AN = 0.0;
    double AP = 0.0;
    double BN = 0.0;
    double BP = 0.0;
    double CN = 0.0;
    double CP = 0.0;
    double Dabc = 0.0;
    double G11 = 0.0;
    double G12 = 0.0;
    double G22 = 0.0;
    double Grc = 0.0;
    double PN = 0.0;
    double PP = 0.0;
    double gNN = 0.0;
    double w1 = 0.0;
    double w2 = 0.0;
    /* User Ihis/history symbols */
    double IAhis_rc = 0.0;
    double IBhis_rc = 0.0;
    double IC_his0 = 0.0;
    double IChis_rc = 0.0;
    double Ihis_A = 0.0;
    double Ihis_B = 0.0;
    double Ihis_C = 0.0;
    double Ihis_a = 0.0;
    double Ihis_b = 0.0;
    double Ihis_c = 0.0;
    double Ihis_exclude_c0 = 0.0;
    double Ihis_exclude_c1 = 0.0;
    double Ihis_exclude_c2 = 0.0;
    double Ihis_exclude_c3 = 0.0;
    double Ihis_exclude_c4 = 0.0;
    /* Block-matrix scalar aliases */
    double Gkk_shared_1 = 0.0;
    double Gkr_k1_N = 0.0;
    double Gkr_k1_P = 0.0;
    double Gkr_k2_N = 0.0;
    double Gkr_k2_P = 0.0;
    double Gkr_k3_N = 0.0;
    double Gkr_k3_P = 0.0;
    double Gkr_shared_1 = 0.0;
    double Gkr_shared_2 = 0.0;
    double Gkr_shared_3 = 0.0;
    double Gkr_shared_4 = 0.0;
    double Grk_N_k1 = 0.0;
    double Grk_N_k2 = 0.0;
    double Grk_N_k3 = 0.0;
    double Grk_P_k1 = 0.0;
    double Grk_P_k2 = 0.0;
    double Grk_P_k3 = 0.0;
    double Grk_shared_1 = 0.0;
    double Grk_shared_2 = 0.0;
    double Grk_shared_3 = 0.0;
    double Grk_shared_4 = 0.0;
    double Grr_G_G = 0.0;
    double Grr_N_N = 0.0;
    double Grr_P_P = 0.0;
    double Grr_shared_1 = 0.0;
    double Grr_shared_2 = 0.0;
    double Grr_shared_3 = 0.0;
    double Grr_shared_4 = 0.0;
    double W_shared_1 = 0.0;

LOCAL_STATIC:
    /* User RAM-only G symbols */
    double gC = 0.0;

RAM_PASS1:
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * Assign or compute every G-related value before any RAM-side use.
     * This section stamps only fixed g_mat_over entries; CODE-owned matrices are refreshed in CODE.
     * ************************************************************************ */



    g_mat_nods[0] = getNodeNum(comp, "P");
    g_mat_nods[1] = getNodeNum(comp, "N");
    /* g_mat_over is provided by the PSYS/CBuilder runtime; initialize, do not define it here. */
    for (int row = 0; row < 2; row++) {
        for (int col = 0; col < 2; col++) {
            g_mat_over[row][col] = 0.0;
        }
    }
    g_mat_over[0][0] = gC;
    g_mat_over[0][1] = -gC;
    g_mat_over[1][0] = -gC;
    g_mat_over[1][1] = gC;
    setupGMatrix(2);

    err += matrixDim(&Grr_code, RETAINED_NODES, RETAINED_NODES);
    err += matrixDim(&Grk_code, RETAINED_NODES, INTERNAL_NODES);
    err += matrixDim(&Gkr_code, INTERNAL_NODES, RETAINED_NODES);
    err += matrixDim(&Gkk_code, INTERNAL_NODES, INTERNAL_NODES);
    err += matrixDim(&Gred_code, RETAINED_NODES, RETAINED_NODES);
    err += matrixDim(&Ihisr_code, RETAINED_NODES, 1);
    err += matrixDim(&Ihisk_code, INTERNAL_NODES, 1);
    err += matrixDim(&Ihisred_code, RETAINED_NODES, 1);
    err += matrixDim(&Vr_code, RETAINED_NODES, 1);
    err += matrixDim(&Vk_code, INTERNAL_NODES, 1);
    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }
    matrix_register(&Grr_code);
    matrix_register(&Grk_code);
    matrix_register(&Gkr_code);
    matrix_register(&Gkk_code);
    matrix_register(&Gred_code);
    matrix_register(&Ihisr_code);
    matrix_register(&Ihisk_code);
    matrix_register(&Ihisred_code);
    matrix_register(&Vr_code);
    matrix_register(&Vk_code);

GVALUES:
    /* Dynamic reduced-G stamp handles, ordered by Gred upper triangle. */
    double varG_A_1_A_1 = createGValue("varG_A_1_A_1", "A_1", "A_1", 0, "TRUE");
    double varG_A_1_B_1 = createGValue("varG_A_1_B_1", "A_1", "B_1", 0, "TRUE");
    double varG_A_1_C_1 = createGValue("varG_A_1_C_1", "A_1", "C_1", 0, "TRUE");
    double varG_A_1_G = createGValue("varG_A_1_G", "A_1", "G", 0, "TRUE");
    double varG_A_1_RC_A = createGValue("varG_A_1_RC_A", "A_1", "RC_A", 0, "TRUE");
    double varG_A_1_RC_C = createGValue("varG_A_1_RC_C", "A_1", "RC_C", 0, "TRUE");
    double varG_A_1_P = createGValue("varG_A_1_P", "A_1", "P", 0, "TRUE");
    double varG_A_1_N = createGValue("varG_A_1_N", "A_1", "N", 0, "TRUE");
    double varG_B_1_B_1 = createGValue("varG_B_1_B_1", "B_1", "B_1", 0, "TRUE");
    double varG_B_1_C_1 = createGValue("varG_B_1_C_1", "B_1", "C_1", 0, "TRUE");
    double varG_B_1_G = createGValue("varG_B_1_G", "B_1", "G", 0, "TRUE");
    double varG_B_1_RC_A = createGValue("varG_B_1_RC_A", "B_1", "RC_A", 0, "TRUE");
    double varG_B_1_RC_B = createGValue("varG_B_1_RC_B", "B_1", "RC_B", 0, "TRUE");
    double varG_B_1_P = createGValue("varG_B_1_P", "B_1", "P", 0, "TRUE");
    double varG_B_1_N = createGValue("varG_B_1_N", "B_1", "N", 0, "TRUE");
    double varG_C_1_C_1 = createGValue("varG_C_1_C_1", "C_1", "C_1", 0, "TRUE");
    double varG_C_1_G = createGValue("varG_C_1_G", "C_1", "G", 0, "TRUE");
    double varG_C_1_RC_B = createGValue("varG_C_1_RC_B", "C_1", "RC_B", 0, "TRUE");
    double varG_C_1_RC_C = createGValue("varG_C_1_RC_C", "C_1", "RC_C", 0, "TRUE");
    double varG_C_1_P = createGValue("varG_C_1_P", "C_1", "P", 0, "TRUE");
    double varG_C_1_N = createGValue("varG_C_1_N", "C_1", "N", 0, "TRUE");
    double varG_G_G = createGValue("varG_G_G", "G", "G", 0, "TRUE");
    double varG_G_RC_A = createGValue("varG_G_RC_A", "G", "RC_A", 0, "TRUE");
    double varG_G_RC_B = createGValue("varG_G_RC_B", "G", "RC_B", 0, "TRUE");
    double varG_G_RC_C = createGValue("varG_G_RC_C", "G", "RC_C", 0, "TRUE");
    double varG_G_P = createGValue("varG_G_P", "G", "P", 0, "TRUE");
    double varG_G_N = createGValue("varG_G_N", "G", "N", 0, "TRUE");
    double varG_RC_A_RC_A = createGValue("varG_RC_A_RC_A", "RC_A", "RC_A", 0, "TRUE");
    double varG_RC_A_P = createGValue("varG_RC_A_P", "RC_A", "P", 0, "TRUE");
    double varG_RC_A_N = createGValue("varG_RC_A_N", "RC_A", "N", 0, "TRUE");
    double varG_RC_B_RC_B = createGValue("varG_RC_B_RC_B", "RC_B", "RC_B", 0, "TRUE");
    double varG_RC_B_P = createGValue("varG_RC_B_P", "RC_B", "P", 0, "TRUE");
    double varG_RC_B_N = createGValue("varG_RC_B_N", "RC_B", "N", 0, "TRUE");
    double varG_RC_C_RC_C = createGValue("varG_RC_C_RC_C", "RC_C", "RC_C", 0, "TRUE");
    double varG_RC_C_P = createGValue("varG_RC_C_P", "RC_C", "P", 0, "TRUE");
    double varG_RC_C_N = createGValue("varG_RC_C_N", "RC_C", "N", 0, "TRUE");
    double varG_P_P = createGValue("varG_P_P", "P", "P", 0, "TRUE");
    double varG_P_N = createGValue("varG_P_N", "P", "N", 0, "TRUE");
    double varG_N_N = createGValue("varG_N_N", "N", "N", 0, "TRUE");

CODE:
BEGIN_T0:
    if (!rtds_matrix_code_ready) {
        initializeMatricesForCode();
        conditionMatrixForCODE(&Grr_code);
        conditionMatrixForCODE(&Grk_code);
        conditionMatrixForCODE(&Gkr_code);
        conditionMatrixForCODE(&Gkk_code);
        conditionMatrixForCODE(&Gred_code);
        conditionMatrixForCODE(&Ihisr_code);
        conditionMatrixForCODE(&Ihisk_code);
        conditionMatrixForCODE(&Ihisred_code);
        conditionMatrixForCODE(&Vr_code);
        conditionMatrixForCODE(&Vk_code);
        rtds_matrix_code_ready = 1;
    }


    /* ************************************************************************
     * CODE-SIDE G MATRIX VALUE SETUP
     * Update runtime G-related symbols and matrices before the reduction math below.
     * Only matrices required by dynamic G, Ihis reduction, or Vk recovery are refreshed.
     * ************************************************************************ */



    /* Runtime refresh. Use set_CODE for matrices touched in CODE; do not write MATRIX_.p directly. */
    /* Grr_shared_1 represents Grr[A_1,A_1], Grr[B_1,B_1], Grr[C_1,C_1]: 2.0*G11 + 2.0*w1. */
    Grr_shared_1 = 2.0*G11 + 2.0*w1;
    /* Grr_shared_2 represents Grr[A_1,B_1], Grr[A_1,C_1], Grr[B_1,A_1], Grr[B_1,C_1], Grr[C_1,A_1], Grr[C_1,B_1]: -G11 - w1. */
    Grr_shared_2 = -G11 - w1;
    /* Grr_G_G represents Grr[G,G]: 3.0*G22 + 3.0*w2. */
    Grr_G_G = 3.0*G22 + 3.0*w2;
    /* Grr_shared_3 represents Grr[RC_A,RC_A], Grr[RC_B,RC_B], Grr[RC_C,RC_C]: Grc. */
    Grr_shared_3 = Grc;
    /* Grr_P_P represents Grr[P,P]: PP. */
    Grr_P_P = PP;
    /* Grr_shared_4 represents Grr[P,N], Grr[N,P]: PN. */
    Grr_shared_4 = PN;
    /* Grr_N_N represents Grr[N,N]: gNN. */
    Grr_N_N = gNN;
    /* Grk_shared_1 represents Grk[A_1,k1], Grk[B_1,k2], Grk[C_1,k3]: G12. */
    Grk_shared_1 = G12;
    /* Grk_shared_2 represents Grk[A_1,k3], Grk[B_1,k1], Grk[C_1,k2]: -G12. */
    Grk_shared_2 = -G12;
    /* Grk_shared_3 represents Grk[G,k1], Grk[G,k2], Grk[G,k3]: -G22 - w2. */
    Grk_shared_3 = -G22 - w2;
    /* Grk_shared_4 represents Grk[RC_A,k1], Grk[RC_B,k2], Grk[RC_C,k3]: -Grc. */
    Grk_shared_4 = -Grc;
    /* Grk_P_k1 represents Grk[P,k1]: AP. */
    Grk_P_k1 = AP;
    /* Grk_P_k2 represents Grk[P,k2]: BP. */
    Grk_P_k2 = BP;
    /* Grk_P_k3 represents Grk[P,k3]: CP. */
    Grk_P_k3 = CP;
    /* Grk_N_k1 represents Grk[N,k1]: AN. */
    Grk_N_k1 = AN;
    /* Grk_N_k2 represents Grk[N,k2]: BN. */
    Grk_N_k2 = BN;
    /* Grk_N_k3 represents Grk[N,k3]: CN. */
    Grk_N_k3 = CN;
    /* Gkr_shared_1 represents Gkr[k1,A_1], Gkr[k2,B_1], Gkr[k3,C_1]: G12. */
    Gkr_shared_1 = G12;
    /* Gkr_shared_2 represents Gkr[k1,B_1], Gkr[k2,C_1], Gkr[k3,A_1]: -G12. */
    Gkr_shared_2 = -G12;
    /* Gkr_shared_3 represents Gkr[k1,G], Gkr[k2,G], Gkr[k3,G]: -G22 - w2. */
    Gkr_shared_3 = -G22 - w2;
    /* Gkr_shared_4 represents Gkr[k1,RC_A], Gkr[k2,RC_B], Gkr[k3,RC_C]: -Grc. */
    Gkr_shared_4 = -Grc;
    /* Gkr_k1_P represents Gkr[k1,P]: AP. */
    Gkr_k1_P = AP;
    /* Gkr_k1_N represents Gkr[k1,N]: AN. */
    Gkr_k1_N = AN;
    /* Gkr_k2_P represents Gkr[k2,P]: BP. */
    Gkr_k2_P = BP;
    /* Gkr_k2_N represents Gkr[k2,N]: BN. */
    Gkr_k2_N = BN;
    /* Gkr_k3_P represents Gkr[k3,P]: CP. */
    Gkr_k3_P = CP;
    /* Gkr_k3_N represents Gkr[k3,N]: CN. */
    Gkr_k3_N = CN;
    /* Gkk_shared_1 represents Gkk[k1,k1], Gkk[k2,k2], Gkk[k3,k3]: Dabc + G22 + Grc + w2. */
    Gkk_shared_1 = Dabc + G22 + Grc + w2;
    /* W_shared_1 represents W[1,1], W[2,2], W[3,3]: 1.0/(Dabc + G22 + Grc + w2). */
    W_shared_1 = 1.0/(Dabc + G22 + Grc + w2);
    set_CODE(&Grr_code, 0, 0, Grr_shared_1);
    set_CODE(&Grr_code, 1, 1, Grr_shared_1);
    set_CODE(&Grr_code, 2, 2, Grr_shared_1);
    set_CODE(&Grr_code, 0, 1, Grr_shared_2);
    set_CODE(&Grr_code, 0, 2, Grr_shared_2);
    set_CODE(&Grr_code, 1, 0, Grr_shared_2);
    set_CODE(&Grr_code, 1, 2, Grr_shared_2);
    set_CODE(&Grr_code, 2, 0, Grr_shared_2);
    set_CODE(&Grr_code, 2, 1, Grr_shared_2);
    set_CODE(&Grr_code, 3, 3, Grr_G_G);
    set_CODE(&Grr_code, 4, 4, Grr_shared_3);
    set_CODE(&Grr_code, 5, 5, Grr_shared_3);
    set_CODE(&Grr_code, 6, 6, Grr_shared_3);
    set_CODE(&Grr_code, 7, 7, Grr_P_P);
    set_CODE(&Grr_code, 7, 8, Grr_shared_4);
    set_CODE(&Grr_code, 8, 7, Grr_shared_4);
    set_CODE(&Grr_code, 8, 8, Grr_N_N);
    set_CODE(&Grk_code, 0, 0, Grk_shared_1);
    set_CODE(&Grk_code, 1, 1, Grk_shared_1);
    set_CODE(&Grk_code, 2, 2, Grk_shared_1);
    set_CODE(&Grk_code, 0, 2, Grk_shared_2);
    set_CODE(&Grk_code, 1, 0, Grk_shared_2);
    set_CODE(&Grk_code, 2, 1, Grk_shared_2);
    set_CODE(&Grk_code, 3, 0, Grk_shared_3);
    set_CODE(&Grk_code, 3, 1, Grk_shared_3);
    set_CODE(&Grk_code, 3, 2, Grk_shared_3);
    set_CODE(&Grk_code, 4, 0, Grk_shared_4);
    set_CODE(&Grk_code, 5, 1, Grk_shared_4);
    set_CODE(&Grk_code, 6, 2, Grk_shared_4);
    set_CODE(&Grk_code, 7, 0, Grk_P_k1);
    set_CODE(&Grk_code, 7, 1, Grk_P_k2);
    set_CODE(&Grk_code, 7, 2, Grk_P_k3);
    set_CODE(&Grk_code, 8, 0, Grk_N_k1);
    set_CODE(&Grk_code, 8, 1, Grk_N_k2);
    set_CODE(&Grk_code, 8, 2, Grk_N_k3);
    set_CODE(&Gkr_code, 0, 0, Gkr_shared_1);
    set_CODE(&Gkr_code, 1, 1, Gkr_shared_1);
    set_CODE(&Gkr_code, 2, 2, Gkr_shared_1);
    set_CODE(&Gkr_code, 0, 1, Gkr_shared_2);
    set_CODE(&Gkr_code, 1, 2, Gkr_shared_2);
    set_CODE(&Gkr_code, 2, 0, Gkr_shared_2);
    set_CODE(&Gkr_code, 0, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 1, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 2, 3, Gkr_shared_3);
    set_CODE(&Gkr_code, 0, 4, Gkr_shared_4);
    set_CODE(&Gkr_code, 1, 5, Gkr_shared_4);
    set_CODE(&Gkr_code, 2, 6, Gkr_shared_4);
    set_CODE(&Gkr_code, 0, 7, Gkr_k1_P);
    set_CODE(&Gkr_code, 0, 8, Gkr_k1_N);
    set_CODE(&Gkr_code, 1, 7, Gkr_k2_P);
    set_CODE(&Gkr_code, 1, 8, Gkr_k2_N);
    set_CODE(&Gkr_code, 2, 7, Gkr_k3_P);
    set_CODE(&Gkr_code, 2, 8, Gkr_k3_N);
    set_CODE(&Gkk_code, 0, 0, Gkk_shared_1);
    set_CODE(&Gkk_code, 1, 1, Gkk_shared_1);
    set_CODE(&Gkk_code, 2, 2, Gkk_shared_1);

    /* ************************************************************************
     * CODE-SIDE IHIS VALUE SETUP
     * Update runtime Ihis/history-source values before per-step injection math.
     * Only non-direct Ihisred rows are computed through MATRIX_ CODE helpers.
     * ************************************************************************ */



    set_CODE(&Ihisr_code, 0, 0, Ihis_A - Ihis_C);
    set_CODE(&Ihisr_code, 1, 0, -Ihis_A + Ihis_B);
    set_CODE(&Ihisr_code, 2, 0, -Ihis_B + Ihis_C);
    set_CODE(&Ihisr_code, 3, 0, -Ihis_a - Ihis_b - Ihis_c);
    set_CODE(&Ihisr_code, 4, 0, -IAhis_rc);
    set_CODE(&Ihisr_code, 5, 0, -IBhis_rc);
    set_CODE(&Ihisr_code, 6, 0, -IChis_rc);
    set_CODE(&Ihisr_code, 7, 0, Ihis_exclude_c3);
    set_CODE(&Ihisr_code, 8, 0, Ihis_exclude_c4);
    set_CODE(&Ihisk_code, 0, 0, IAhis_rc + Ihis_a + Ihis_exclude_c0);
    set_CODE(&Ihisk_code, 1, 0, IBhis_rc + Ihis_b + Ihis_exclude_c1);
    set_CODE(&Ihisk_code, 2, 0, IChis_rc + Ihis_c + Ihis_exclude_c2);

    /* Sliced Schur sparse updates for dynamic Gred entries.
       Each assignment uses Gred[i,j] = Grr[i,j] - Grk[i,k] * W * Gkr[k,j]. */
    /* Stamp dynamic Gred entries directly from the sliced dynamic block. */
    /* varG_A_1_A_1 represents Gred[A_1,A_1]: Grr_shared_1 - Grk_shared_1*W_shared_1*Gkr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2. */
    /* Gred[A_1,A_1] = Grr[A_1,A_1] - Grk[A_1,k] * W * Gkr[k,A_1]. */
    varG_A_1_A_1 = Grr_shared_1 - Grk_shared_1*W_shared_1*Gkr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2;
    /* varG_A_1_B_1 represents Gred[A_1,B_1]: Grr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_2. */
    /* Gred[A_1,B_1] = Grr[A_1,B_1] - Grk[A_1,k] * W * Gkr[k,B_1]. */
    varG_A_1_B_1 = Grr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_2;
    /* varG_A_1_C_1 represents Gred[A_1,C_1]: Grr_shared_2 - Grk_shared_2*W_shared_1*Gkr_shared_1. */
    /* Gred[A_1,C_1] = Grr[A_1,C_1] - Grk[A_1,k] * W * Gkr[k,C_1]. */
    varG_A_1_C_1 = Grr_shared_2 - Grk_shared_2*W_shared_1*Gkr_shared_1;
    /* varG_A_1_G represents Gred[A_1,G]: -Grk_shared_1*W_shared_1*Gkr_shared_3 - Grk_shared_2*W_shared_1*Gkr_shared_3. */
    /* Gred[A_1,G] = Grr[A_1,G] - Grk[A_1,k] * W * Gkr[k,G]. */
    varG_A_1_G = -Grk_shared_1*W_shared_1*Gkr_shared_3 - Grk_shared_2*W_shared_1*Gkr_shared_3;
    /* varG_A_1_RC_A represents Gred[A_1,RC_A]: -Grk_shared_1*W_shared_1*Gkr_shared_4. */
    /* Gred[A_1,RC_A] = Grr[A_1,RC_A] - Grk[A_1,k] * W * Gkr[k,RC_A]. */
    varG_A_1_RC_A = -Grk_shared_1*W_shared_1*Gkr_shared_4;
    /* varG_A_1_RC_C represents Gred[A_1,RC_C]: -Grk_shared_2*W_shared_1*Gkr_shared_4. */
    /* Gred[A_1,RC_C] = Grr[A_1,RC_C] - Grk[A_1,k] * W * Gkr[k,RC_C]. */
    varG_A_1_RC_C = -Grk_shared_2*W_shared_1*Gkr_shared_4;
    /* varG_A_1_P represents Gred[A_1,P]: -Grk_shared_1*W_shared_1*Gkr_k1_P - Grk_shared_2*W_shared_1*Gkr_k3_P. */
    /* Gred[A_1,P] = Grr[A_1,P] - Grk[A_1,k] * W * Gkr[k,P]. */
    varG_A_1_P = -Grk_shared_1*W_shared_1*Gkr_k1_P - Grk_shared_2*W_shared_1*Gkr_k3_P;
    /* varG_A_1_N represents Gred[A_1,N]: -Grk_shared_1*W_shared_1*Gkr_k1_N - Grk_shared_2*W_shared_1*Gkr_k3_N. */
    /* Gred[A_1,N] = Grr[A_1,N] - Grk[A_1,k] * W * Gkr[k,N]. */
    varG_A_1_N = -Grk_shared_1*W_shared_1*Gkr_k1_N - Grk_shared_2*W_shared_1*Gkr_k3_N;
    /* varG_B_1_B_1 represents Gred[B_1,B_1]: Grr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_1. */
    /* Gred[B_1,B_1] = Grr[B_1,B_1] - Grk[B_1,k] * W * Gkr[k,B_1]. */
    varG_B_1_B_1 = Grr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_1;
    /* varG_B_1_C_1 represents Gred[B_1,C_1]: Grr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_2. */
    /* Gred[B_1,C_1] = Grr[B_1,C_1] - Grk[B_1,k] * W * Gkr[k,C_1]. */
    varG_B_1_C_1 = Grr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_2;
    /* varG_B_1_G represents Gred[B_1,G]: -Grk_shared_2*W_shared_1*Gkr_shared_3 - Grk_shared_1*W_shared_1*Gkr_shared_3. */
    /* Gred[B_1,G] = Grr[B_1,G] - Grk[B_1,k] * W * Gkr[k,G]. */
    varG_B_1_G = -Grk_shared_2*W_shared_1*Gkr_shared_3 - Grk_shared_1*W_shared_1*Gkr_shared_3;
    /* varG_B_1_RC_A reuses Gred[B_1,RC_A]: -varG_A_1_RC_A. */
    varG_B_1_RC_A = -varG_A_1_RC_A;
    /* varG_B_1_RC_B represents Gred[B_1,RC_B]: -Grk_shared_1*W_shared_1*Gkr_shared_4. */
    /* Gred[B_1,RC_B] = Grr[B_1,RC_B] - Grk[B_1,k] * W * Gkr[k,RC_B]. */
    varG_B_1_RC_B = -Grk_shared_1*W_shared_1*Gkr_shared_4;
    /* varG_B_1_P represents Gred[B_1,P]: -Grk_shared_2*W_shared_1*Gkr_k1_P - Grk_shared_1*W_shared_1*Gkr_k2_P. */
    /* Gred[B_1,P] = Grr[B_1,P] - Grk[B_1,k] * W * Gkr[k,P]. */
    varG_B_1_P = -Grk_shared_2*W_shared_1*Gkr_k1_P - Grk_shared_1*W_shared_1*Gkr_k2_P;
    /* varG_B_1_N represents Gred[B_1,N]: -Grk_shared_2*W_shared_1*Gkr_k1_N - Grk_shared_1*W_shared_1*Gkr_k2_N. */
    /* Gred[B_1,N] = Grr[B_1,N] - Grk[B_1,k] * W * Gkr[k,N]. */
    varG_B_1_N = -Grk_shared_2*W_shared_1*Gkr_k1_N - Grk_shared_1*W_shared_1*Gkr_k2_N;
    /* varG_C_1_C_1 represents Gred[C_1,C_1]: Grr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_1. */
    /* Gred[C_1,C_1] = Grr[C_1,C_1] - Grk[C_1,k] * W * Gkr[k,C_1]. */
    varG_C_1_C_1 = Grr_shared_1 - Grk_shared_2*W_shared_1*Gkr_shared_2 - Grk_shared_1*W_shared_1*Gkr_shared_1;
    /* varG_C_1_G represents Gred[C_1,G]: -Grk_shared_2*W_shared_1*Gkr_shared_3 - Grk_shared_1*W_shared_1*Gkr_shared_3. */
    /* Gred[C_1,G] = Grr[C_1,G] - Grk[C_1,k] * W * Gkr[k,G]. */
    varG_C_1_G = -Grk_shared_2*W_shared_1*Gkr_shared_3 - Grk_shared_1*W_shared_1*Gkr_shared_3;
    /* varG_C_1_RC_B reuses Gred[C_1,RC_B]: -varG_B_1_RC_B. */
    varG_C_1_RC_B = -varG_B_1_RC_B;
    /* varG_C_1_RC_C reuses Gred[C_1,RC_C]: -varG_A_1_RC_C. */
    varG_C_1_RC_C = -varG_A_1_RC_C;
    /* varG_C_1_P represents Gred[C_1,P]: -Grk_shared_2*W_shared_1*Gkr_k2_P - Grk_shared_1*W_shared_1*Gkr_k3_P. */
    /* Gred[C_1,P] = Grr[C_1,P] - Grk[C_1,k] * W * Gkr[k,P]. */
    varG_C_1_P = -Grk_shared_2*W_shared_1*Gkr_k2_P - Grk_shared_1*W_shared_1*Gkr_k3_P;
    /* varG_C_1_N represents Gred[C_1,N]: -Grk_shared_2*W_shared_1*Gkr_k2_N - Grk_shared_1*W_shared_1*Gkr_k3_N. */
    /* Gred[C_1,N] = Grr[C_1,N] - Grk[C_1,k] * W * Gkr[k,N]. */
    varG_C_1_N = -Grk_shared_2*W_shared_1*Gkr_k2_N - Grk_shared_1*W_shared_1*Gkr_k3_N;
    /* varG_G_G represents Gred[G,G]: Grr_G_G - Grk_shared_3*W_shared_1*Gkr_shared_3 - Grk_shared_3*W_shared_1*Gkr_shared_3 - Grk_shared_3*W_shared_1*Gkr_shared_3. */
    /* Gred[G,G] = Grr[G,G] - Grk[G,k] * W * Gkr[k,G]. */
    varG_G_G = Grr_G_G - Grk_shared_3*W_shared_1*Gkr_shared_3 - Grk_shared_3*W_shared_1*Gkr_shared_3 - Grk_shared_3*W_shared_1*Gkr_shared_3;
    /* varG_G_RC_A represents Gred[G,RC_A]: -Grk_shared_3*W_shared_1*Gkr_shared_4. */
    /* Gred[G,RC_A] = Grr[G,RC_A] - Grk[G,k] * W * Gkr[k,RC_A]. */
    varG_G_RC_A = -Grk_shared_3*W_shared_1*Gkr_shared_4;
    /* varG_G_RC_B represents Gred[G,RC_B]: -Grk_shared_3*W_shared_1*Gkr_shared_4. */
    /* Gred[G,RC_B] = Grr[G,RC_B] - Grk[G,k] * W * Gkr[k,RC_B]. */
    varG_G_RC_B = -Grk_shared_3*W_shared_1*Gkr_shared_4;
    /* varG_G_RC_C represents Gred[G,RC_C]: -Grk_shared_3*W_shared_1*Gkr_shared_4. */
    /* Gred[G,RC_C] = Grr[G,RC_C] - Grk[G,k] * W * Gkr[k,RC_C]. */
    varG_G_RC_C = -Grk_shared_3*W_shared_1*Gkr_shared_4;
    /* varG_G_P represents Gred[G,P]: -Grk_shared_3*W_shared_1*Gkr_k1_P - Grk_shared_3*W_shared_1*Gkr_k2_P - Grk_shared_3*W_shared_1*Gkr_k3_P. */
    /* Gred[G,P] = Grr[G,P] - Grk[G,k] * W * Gkr[k,P]. */
    varG_G_P = -Grk_shared_3*W_shared_1*Gkr_k1_P - Grk_shared_3*W_shared_1*Gkr_k2_P - Grk_shared_3*W_shared_1*Gkr_k3_P;
    /* varG_G_N represents Gred[G,N]: -Grk_shared_3*W_shared_1*Gkr_k1_N - Grk_shared_3*W_shared_1*Gkr_k2_N - Grk_shared_3*W_shared_1*Gkr_k3_N. */
    /* Gred[G,N] = Grr[G,N] - Grk[G,k] * W * Gkr[k,N]. */
    varG_G_N = -Grk_shared_3*W_shared_1*Gkr_k1_N - Grk_shared_3*W_shared_1*Gkr_k2_N - Grk_shared_3*W_shared_1*Gkr_k3_N;
    /* varG_RC_A_RC_A represents Gred[RC_A,RC_A]: Grr_shared_3 - Grk_shared_4*W_shared_1*Gkr_shared_4. */
    /* Gred[RC_A,RC_A] = Grr[RC_A,RC_A] - Grk[RC_A,k] * W * Gkr[k,RC_A]. */
    varG_RC_A_RC_A = Grr_shared_3 - Grk_shared_4*W_shared_1*Gkr_shared_4;
    /* varG_RC_A_P represents Gred[RC_A,P]: -Grk_shared_4*W_shared_1*Gkr_k1_P. */
    /* Gred[RC_A,P] = Grr[RC_A,P] - Grk[RC_A,k] * W * Gkr[k,P]. */
    varG_RC_A_P = -Grk_shared_4*W_shared_1*Gkr_k1_P;
    /* varG_RC_A_N represents Gred[RC_A,N]: -Grk_shared_4*W_shared_1*Gkr_k1_N. */
    /* Gred[RC_A,N] = Grr[RC_A,N] - Grk[RC_A,k] * W * Gkr[k,N]. */
    varG_RC_A_N = -Grk_shared_4*W_shared_1*Gkr_k1_N;
    /* varG_RC_B_RC_B represents Gred[RC_B,RC_B]: Grr_shared_3 - Grk_shared_4*W_shared_1*Gkr_shared_4. */
    /* Gred[RC_B,RC_B] = Grr[RC_B,RC_B] - Grk[RC_B,k] * W * Gkr[k,RC_B]. */
    varG_RC_B_RC_B = Grr_shared_3 - Grk_shared_4*W_shared_1*Gkr_shared_4;
    /* varG_RC_B_P represents Gred[RC_B,P]: -Grk_shared_4*W_shared_1*Gkr_k2_P. */
    /* Gred[RC_B,P] = Grr[RC_B,P] - Grk[RC_B,k] * W * Gkr[k,P]. */
    varG_RC_B_P = -Grk_shared_4*W_shared_1*Gkr_k2_P;
    /* varG_RC_B_N represents Gred[RC_B,N]: -Grk_shared_4*W_shared_1*Gkr_k2_N. */
    /* Gred[RC_B,N] = Grr[RC_B,N] - Grk[RC_B,k] * W * Gkr[k,N]. */
    varG_RC_B_N = -Grk_shared_4*W_shared_1*Gkr_k2_N;
    /* varG_RC_C_RC_C represents Gred[RC_C,RC_C]: Grr_shared_3 - Grk_shared_4*W_shared_1*Gkr_shared_4. */
    /* Gred[RC_C,RC_C] = Grr[RC_C,RC_C] - Grk[RC_C,k] * W * Gkr[k,RC_C]. */
    varG_RC_C_RC_C = Grr_shared_3 - Grk_shared_4*W_shared_1*Gkr_shared_4;
    /* varG_RC_C_P represents Gred[RC_C,P]: -Grk_shared_4*W_shared_1*Gkr_k3_P. */
    /* Gred[RC_C,P] = Grr[RC_C,P] - Grk[RC_C,k] * W * Gkr[k,P]. */
    varG_RC_C_P = -Grk_shared_4*W_shared_1*Gkr_k3_P;
    /* varG_RC_C_N represents Gred[RC_C,N]: -Grk_shared_4*W_shared_1*Gkr_k3_N. */
    /* Gred[RC_C,N] = Grr[RC_C,N] - Grk[RC_C,k] * W * Gkr[k,N]. */
    varG_RC_C_N = -Grk_shared_4*W_shared_1*Gkr_k3_N;
    /* varG_P_P represents Gred[P,P]: Grr_P_P - Grk_P_k1*W_shared_1*Gkr_k1_P - Grk_P_k2*W_shared_1*Gkr_k2_P - Grk_P_k3*W_shared_1*Gkr_k3_P. */
    /* Gred[P,P] = Grr[P,P] - Grk[P,k] * W * Gkr[k,P]. */
    varG_P_P = Grr_P_P - Grk_P_k1*W_shared_1*Gkr_k1_P - Grk_P_k2*W_shared_1*Gkr_k2_P - Grk_P_k3*W_shared_1*Gkr_k3_P;
    /* varG_P_N represents Gred[P,N]: Grr_shared_4 - Grk_P_k1*W_shared_1*Gkr_k1_N - Grk_P_k2*W_shared_1*Gkr_k2_N - Grk_P_k3*W_shared_1*Gkr_k3_N. */
    /* Gred[P,N] = Grr[P,N] - Grk[P,k] * W * Gkr[k,N]. */
    varG_P_N = Grr_shared_4 - Grk_P_k1*W_shared_1*Gkr_k1_N - Grk_P_k2*W_shared_1*Gkr_k2_N - Grk_P_k3*W_shared_1*Gkr_k3_N;
    /* varG_N_N represents Gred[N,N]: Grr_N_N - Grk_N_k1*W_shared_1*Gkr_k1_N - Grk_N_k2*W_shared_1*Gkr_k2_N - Grk_N_k3*W_shared_1*Gkr_k3_N. */
    /* Gred[N,N] = Grr[N,N] - Grk[N,k] * W * Gkr[k,N]. */
    varG_N_N = Grr_N_N - Grk_N_k1*W_shared_1*Gkr_k1_N - Grk_N_k2*W_shared_1*Gkr_k2_N - Grk_N_k3*W_shared_1*Gkr_k3_N;

    /* Ihisred is a per-step injection vector: Ihisred = Ihisr - Grk * W * Ihisk. */
    /* Diagonal Gkk scalar CODE path: Ihisred = Ihisr - sum_k Grk[i,k] * Ihisk[k] / Gkk[k,k]. */
    {
        double inv_gkk_diag[INTERNAL_NODES];
        for (int k = 0; k < INTERNAL_NODES; k++) {
            inv_gkk_diag[k] = 1.0 / get_CODE(&Gkk_code, k, k);
        }
        for (int i = 0; i < RETAINED_NODES; i++) {
            double ihis = get_CODE(&Ihisr_code, i, 0);
            for (int k = 0; k < INTERNAL_NODES; k++) {
                ihis -= get_CODE(&Grk_code, i, k) * get_CODE(&Ihisk_code, k, 0) * inv_gkk_diag[k];
            }
            set_CODE(&Ihisred_code, i, 0, ihis);
        }
    }
    set_CODE(&Ihisred_code, 7, 0, get_CODE(&Ihisred_code, 7, 0) + IC_his0);
    set_CODE(&Ihisred_code, 8, 0, get_CODE(&Ihisred_code, 8, 0) + -IC_his0);
    /* Node injection currents follow the retained-node order of the reduced system. */
    InjA_1 = get_CODE(&Ihisred_code, 0, 0);
    InjB_1 = get_CODE(&Ihisred_code, 1, 0);
    InjC_1 = get_CODE(&Ihisred_code, 2, 0);
    InjG = get_CODE(&Ihisred_code, 3, 0);
    InjRC_A = get_CODE(&Ihisred_code, 4, 0);
    InjRC_B = get_CODE(&Ihisred_code, 5, 0);
    InjRC_C = get_CODE(&Ihisred_code, 6, 0);
    InjP = get_CODE(&Ihisred_code, 7, 0);
    InjN = get_CODE(&Ihisred_code, 8, 0);

T1_T2:
    /* Internal-node voltage recovery after solved retained-node voltages are available. */
    set_CODE(&Vr_code, 0, 0, A_1);
    set_CODE(&Vr_code, 1, 0, B_1);
    set_CODE(&Vr_code, 2, 0, C_1);
    set_CODE(&Vr_code, 3, 0, G);
    set_CODE(&Vr_code, 4, 0, RC_A);
    set_CODE(&Vr_code, 5, 0, RC_B);
    set_CODE(&Vr_code, 6, 0, RC_C);
    set_CODE(&Vr_code, 7, 0, P);
    set_CODE(&Vr_code, 8, 0, N);
    /* Diagonal Gkk scalar CODE path: Vk[k] = -(Gkr[k,*] * Vr + Ihisk[k]) / Gkk[k,k]. */
    {
        double inv_gkk_diag[INTERNAL_NODES];
        for (int k = 0; k < INTERNAL_NODES; k++) {
            inv_gkk_diag[k] = 1.0 / get_CODE(&Gkk_code, k, k);
        }
        for (int k = 0; k < INTERNAL_NODES; k++) {
            double vk_sum = 0.0;
            for (int j = 0; j < RETAINED_NODES; j++) {
                vk_sum += get_CODE(&Gkr_code, k, j) * get_CODE(&Vr_code, j, 0);
            }
            vk_sum += get_CODE(&Ihisk_code, k, 0);
            set_CODE(&Vk_code, k, 0, -vk_sum * inv_gkk_diag[k]);
        }
    }

    /* One variable per eliminated node, in effective k order. */
    a = get_CODE(&Vk_code, 0, 0);
    b = get_CODE(&Vk_code, 1, 0);
    c = get_CODE(&Vk_code, 2, 0);

