        mat_3x3_sym_inv_code(get_CODE(&Gkk_code, 0, 0), get_CODE(&Gkk_code, 0, 1), get_CODE(&Gkk_code, 0, 2),
                             get_CODE(&Gkk_code, 1, 1), get_CODE(&Gkk_code, 1, 2),
                             get_CODE(&Gkk_code, 2, 2),
                             &W_code_11, &W_code_12, &W_code_13,
                             &W_code_22, &W_code_23,
                             &W_code_33);
        set_CODE(&W_code, 0, 0, W_code_11);
        set_CODE(&W_code, 0, 1, W_code_12);
        set_CODE(&W_code, 0, 2, W_code_13);
        set_CODE(&W_code, 1, 0, W_code_12);
        set_CODE(&W_code, 1, 1, W_code_22);
        set_CODE(&W_code, 1, 2, W_code_23);
        set_CODE(&W_code, 2, 0, W_code_13);
        set_CODE(&W_code, 2, 1, W_code_23);
        set_CODE(&W_code, 2, 2, W_code_33);
        break;
    }
    }

    /* ************************************************************************
     * CODE-SIDE IHIS VALUE SETUP
     * Update runtime Ihis/history-source values before per-step injection math.
     * Only non-direct Ihisred rows are computed through MATRIX_ CODE helpers.
     * ************************************************************************ */


    set_CODE(&Ihisr_code, 0, 0, multcase_Ihis_C1_N1);
    set_CODE(&Ihisr_code, 1, 0, multcase_Ihis_C1_N2);
    set_CODE(&Ihisr_code, 2, 0, multcase_Ihis_C1_N3);
    set_CODE(&Ihisr_code, 3, 0, -multcase_Ihis_C1_N4);
    set_CODE(&Ihisr_code, 4, 0, Ihis_exclude_c3);
    set_CODE(&Ihisr_code, 5, 0, Ihis_exclude_c4);
    if (retained_profile == PACK_CASE_0) {
        set_CODE(&Ihisr_code, 6, 0, -multcase_Ihis_C3_N10);
        set_CODE(&Ihisr_code, 7, 0, -multcase_Ihis_C3_N11);
        set_CODE(&Ihisr_code, 8, 0, -multcase_Ihis_C3_N12);
    }
    set_CODE(&Ihisk_code, 0, 0, multcase_Ihis_combined_N5);
    set_CODE(&Ihisk_code, 1, 0, multcase_Ihis_combined_N6);
    set_CODE(&Ihisk_code, 2, 0, multcase_Ihis_combined_N7);

    /* Case-resolved diagonal Gkk scalar Schur/Ihis path. */
    switch (case_id) {
    case 2:
    {
        /* Diagonal Gkk scalar Schur path: reuse W[k,k] = 1/Gkk[k,k]. */
        for (int row = 0; row < node_active; row++) {
            for (int k = 0; k < INTERNAL_NODES; k++) {
                double grk_w = get_CODE(&Grk_code, row, k) * get_CODE(&W_code, k, k);
                set_CODE(&tmp_Grk_W_code, row, k, grk_w);
            }
        }
        for (int row = 0; row < node_active; row++) {
            for (int col = row; col < node_active; col++) {
                double schur_acc = 0.0;
                for (int k = 0; k < INTERNAL_NODES; k++) {
                    schur_acc += get_CODE(&tmp_Grk_W_code, row, k) * get_CODE(&Gkr_code, k, col);
                }
                set_CODE(&Gred_code, row, col, get_CODE(&Grr_code, row, col) - schur_acc);
            }
        }
        break;
    }
    case 0:
    case 1:
    case 3:
    {
        matrix_mult_CODE(&tmp_Grk_W_code, &Grk_code, &W_code);
        /* Full Gred CODE path: compute the dense product, then write only the upper triangle used by GValue stamps. */
        /* Symmetric product: only upper triangle of tmp_Grk_W_Gkr_code is needed downstream. */
        for (int row = 0; row < node_active; row++) {
            for (int col = row; col < node_active; col++) {
                double acc = 0.0;
                for (int k = 0; k < INTERNAL_NODES; k++) {
                    acc += get_CODE(&tmp_Grk_W_code, row, k) * get_CODE(&Gkr_code, k, col);
                }
                set_CODE(&tmp_Grk_W_Gkr_code, row, col, acc);
            }
        }
        for (int row = 0; row < node_active; row++) {
            for (int col = row; col < node_active; col++) {
                set_CODE(&Gred_code, row, col, get_CODE(&Grr_code, row, col) - get_CODE(&tmp_Grk_W_Gkr_code, row, col));
            }
        }
        break;
    }
    default:
    {
        matrix_mult_CODE(&tmp_Grk_W_code, &Grk_code, &W_code);
        /* Full Gred CODE path: compute the dense product, then write only the upper triangle used by GValue stamps. */
        /* Symmetric product: only upper triangle of tmp_Grk_W_Gkr_code is needed downstream. */
        for (int row = 0; row < node_active; row++) {
            for (int col = row; col < node_active; col++) {
                double acc = 0.0;
                for (int k = 0; k < INTERNAL_NODES; k++) {
                    acc += get_CODE(&tmp_Grk_W_code, row, k) * get_CODE(&Gkr_code, k, col);
                }
                set_CODE(&tmp_Grk_W_Gkr_code, row, col, acc);
            }
        }
        for (int row = 0; row < node_active; row++) {
            for (int col = row; col < node_active; col++) {
                set_CODE(&Gred_code, row, col, get_CODE(&Grr_code, row, col) - get_CODE(&tmp_Grk_W_Gkr_code, row, col));
            }
        }
        break;
    }
    }
    /* Stamp dynamic Gred entries in row-major upper-triangular order. */
    varG_A_1_A_1 = get_CODE(&Gred_code, 0, 0);
    varG_A_1_B_1 = get_CODE(&Gred_code, 0, 1);
    varG_A_1_C_1 = get_CODE(&Gred_code, 0, 2);
    varG_A_1_G = get_CODE(&Gred_code, 0, 3);
    varG_A_1_P = get_CODE(&Gred_code, 0, 4);
    varG_A_1_N = get_CODE(&Gred_code, 0, 5);
    varG_B_1_B_1 = get_CODE(&Gred_code, 1, 1);
    varG_B_1_C_1 = get_CODE(&Gred_code, 1, 2);
    varG_B_1_P = get_CODE(&Gred_code, 1, 4);
    varG_B_1_N = get_CODE(&Gred_code, 1, 5);
    varG_C_1_C_1 = get_CODE(&Gred_code, 2, 2);
    varG_C_1_P = get_CODE(&Gred_code, 2, 4);
    varG_C_1_N = get_CODE(&Gred_code, 2, 5);
    varG_G_G = get_CODE(&Gred_code, 3, 3);
    varG_G_P = get_CODE(&Gred_code, 3, 4);
    varG_G_N = get_CODE(&Gred_code, 3, 5);
    varG_P_P = get_CODE(&Gred_code, 4, 4);
    varG_P_N = get_CODE(&Gred_code, 4, 5);
    varG_N_N = get_CODE(&Gred_code, 5, 5);

    switch (case_id) {
    case 0:
        varG_A_1_RC_A = get_CODE(&Gred_code, 0, 6);
        varG_A_1_RC_B = get_CODE(&Gred_code, 0, 7);
        varG_A_1_RC_C = get_CODE(&Gred_code, 0, 8);
        varG_B_1_G = varG_A_1_G;
        varG_B_1_RC_A = get_CODE(&Gred_code, 1, 6);
        varG_B_1_RC_B = get_CODE(&Gred_code, 1, 7);
        varG_B_1_RC_C = get_CODE(&Gred_code, 1, 8);
        varG_C_1_G = varG_A_1_G;
        varG_C_1_RC_A = get_CODE(&Gred_code, 2, 6);
        varG_C_1_RC_B = get_CODE(&Gred_code, 2, 7);
        varG_C_1_RC_C = get_CODE(&Gred_code, 2, 8);
        varG_G_RC_A = get_CODE(&Gred_code, 3, 6);
        varG_G_RC_B = get_CODE(&Gred_code, 3, 7);
        varG_G_RC_C = get_CODE(&Gred_code, 3, 8);
        varG_P_RC_A = get_CODE(&Gred_code, 4, 6);
        varG_P_RC_B = get_CODE(&Gred_code, 4, 7);
        varG_P_RC_C = get_CODE(&Gred_code, 4, 8);
        varG_N_RC_A = get_CODE(&Gred_code, 5, 6);
        varG_N_RC_B = get_CODE(&Gred_code, 5, 7);
        varG_N_RC_C = get_CODE(&Gred_code, 5, 8);
        varG_RC_A_RC_A = get_CODE(&Gred_code, 6, 6);
        varG_RC_A_RC_B = get_CODE(&Gred_code, 6, 7);
        varG_RC_A_RC_C = get_CODE(&Gred_code, 6, 8);
        varG_RC_B_RC_B = get_CODE(&Gred_code, 7, 7);
        varG_RC_B_RC_C = get_CODE(&Gred_code, 7, 8);
        varG_RC_C_RC_C = get_CODE(&Gred_code, 8, 8);
        break;
    case 1:
        varG_B_1_G = varG_A_1_G;
        varG_C_1_G = varG_A_1_G;
        break;
    case 2:
        varG_A_1_RC_A = get_CODE(&Gred_code, 0, 6);
        varG_A_1_RC_B = get_CODE(&Gred_code, 0, 7);
        varG_A_1_RC_C = get_CODE(&Gred_code, 0, 8);
        varG_B_1_G = get_CODE(&Gred_code, 1, 3);
        varG_B_1_RC_A = -varG_A_1_RC_A;
        varG_B_1_RC_B = get_CODE(&Gred_code, 1, 7);
        varG_B_1_RC_C = get_CODE(&Gred_code, 1, 8);
        varG_C_1_G = get_CODE(&Gred_code, 2, 3);
        varG_C_1_RC_A = get_CODE(&Gred_code, 2, 6);
        varG_C_1_RC_B = -varG_B_1_RC_B;
        varG_C_1_RC_C = -varG_A_1_RC_C;
        varG_G_RC_A = get_CODE(&Gred_code, 3, 6);
        varG_G_RC_B = get_CODE(&Gred_code, 3, 7);
        varG_G_RC_C = get_CODE(&Gred_code, 3, 8);
        varG_P_RC_A = get_CODE(&Gred_code, 4, 6);
        varG_P_RC_B = get_CODE(&Gred_code, 4, 7);
        varG_P_RC_C = get_CODE(&Gred_code, 4, 8);
        varG_N_RC_A = get_CODE(&Gred_code, 5, 6);
        varG_N_RC_B = get_CODE(&Gred_code, 5, 7);
        varG_N_RC_C = get_CODE(&Gred_code, 5, 8);
        varG_RC_A_RC_A = get_CODE(&Gred_code, 6, 6);
        varG_RC_A_RC_B = get_CODE(&Gred_code, 6, 7);
        varG_RC_A_RC_C = get_CODE(&Gred_code, 6, 8);
        varG_RC_B_RC_B = get_CODE(&Gred_code, 7, 7);
        varG_RC_B_RC_C = get_CODE(&Gred_code, 7, 8);
        varG_RC_C_RC_C = get_CODE(&Gred_code, 8, 8);
        break;
    case 3:
        varG_B_1_G = get_CODE(&Gred_code, 1, 3);
        varG_C_1_G = get_CODE(&Gred_code, 2, 3);
        break;
    default:
        break;
    }


    /* Ihisred is a per-step injection vector: Ihisred = Ihisr - Grk * W * Ihisk. */
    /* Case-resolved diagonal Gkk scalar Ihisred path. */
    switch (case_id) {
    case 2:
    {
        /* Diagonal Gkk scalar Ihisred path: Ihisred = Ihisr - tmp_Grk_W * Ihisk. */
        for (int row = 0; row < node_active; row++) {
            double ihis_acc = 0.0;
            for (int k = 0; k < INTERNAL_NODES; k++) {
                ihis_acc += get_CODE(&tmp_Grk_W_code, row, k) * get_CODE(&Ihisk_code, k, 0);
            }
            set_CODE(&Ihisred_code, row, 0, get_CODE(&Ihisr_code, row, 0) - ihis_acc);
        }
        break;
    }
    case 0:
    case 1:
    case 3:
    {
        matrix_matXvec_CODE(&tmp_Grk_W_Ihisk_code, &tmp_Grk_W_code, &Ihisk_code);
        matrix_subtract_CODE(&Ihisred_code, &Ihisr_code, &tmp_Grk_W_Ihisk_code);
        break;
    }
    default:
    {
        matrix_matXvec_CODE(&tmp_Grk_W_Ihisk_code, &tmp_Grk_W_code, &Ihisk_code);
        matrix_subtract_CODE(&Ihisred_code, &Ihisr_code, &tmp_Grk_W_Ihisk_code);
        break;
    }
    }
    set_CODE(&Ihisred_code, 4, 0, get_CODE(&Ihisred_code, 4, 0) + IC_his0);
    set_CODE(&Ihisred_code, 5, 0, get_CODE(&Ihisred_code, 5, 0) + -IC_his0);
    /* Node injection currents follow the retained-node order of the reduced system. */
    InjA_1 = get_CODE(&Ihisred_code, 0, 0);
    InjB_1 = get_CODE(&Ihisred_code, 1, 0);
    InjC_1 = get_CODE(&Ihisred_code, 2, 0);
    InjG = get_CODE(&Ihisred_code, 3, 0);
    InjP = get_CODE(&Ihisred_code, 4, 0);
    InjN = get_CODE(&Ihisred_code, 5, 0);
    switch (case_id) {
    case 0:
    case 2:
        InjRC_A = get_CODE(&Ihisred_code, 6, 0);
        InjRC_B = get_CODE(&Ihisred_code, 7, 0);
        InjRC_C = get_CODE(&Ihisred_code, 8, 0);
        break;
    default:
        break;
    }



T1_T2:
    /* Internal-node voltage recovery after solved retained-node voltages are available. */
    set_CODE(&Vr_code, 0, 0, A_1);
    set_CODE(&Vr_code, 1, 0, B_1);
    set_CODE(&Vr_code, 2, 0, C_1);
    set_CODE(&Vr_code, 3, 0, G);
    set_CODE(&Vr_code, 4, 0, P);
    set_CODE(&Vr_code, 5, 0, N);
    if (retained_profile == PACK_CASE_0) {
        set_CODE(&Vr_code, 6, 0, RC_A);
        set_CODE(&Vr_code, 7, 0, RC_B);
        set_CODE(&Vr_code, 8, 0, RC_C);
    }
    /* Case-resolved diagonal Gkk scalar Vk recovery path. */
    switch (case_id) {
    case 2:
    {
        /* Diagonal Gkk scalar recovery: W*Gkr is transpose(tmp_Grk_W). */
        for (int k = 0; k < INTERNAL_NODES; k++) {
            double core_v = 0.0;
            for (int col = 0; col < node_active; col++) {
                core_v += get_CODE(&tmp_Grk_W_code, col, k) * get_CODE(&Vr_code, col, 0);
            }
            double hist_v = get_CODE(&Ihisk_code, k, 0) * get_CODE(&W_code, k, k);
            set_CODE(&Vk_code, k, 0, -(core_v + hist_v));
        }
        break;
    }
    case 0:
    case 1:
    case 3:
    {
        /* Symmetry reuse: W * Gkr = transpose(Grk * W). */
        for (int row = 0; row < INTERNAL_NODES; row++) {
            for (int col = 0; col < node_active; col++) {
                set_CODE(&tmp_W_Gkr_code, row, col, get_CODE(&tmp_Grk_W_code, col, row));
            }
        }
        matrix_matXvec_CODE(&tmp_W_Gkr_Vr_code, &tmp_W_Gkr_code, &Vr_code);
        matrix_matXvec_CODE(&tmp_W_Ihisk_code, &W_code, &Ihisk_code);
        matrix_add_CODE(&tmp_Vk_sum_code, &tmp_W_Gkr_Vr_code, &tmp_W_Ihisk_code);
        matrix_scalarMult_CODE(&Vk_code, &tmp_Vk_sum_code, -1.0);
        break;
    }
    default:
    {
        /* Symmetry reuse: W * Gkr = transpose(Grk * W). */
        for (int row = 0; row < INTERNAL_NODES; row++) {
            for (int col = 0; col < node_active; col++) {
                set_CODE(&tmp_W_Gkr_code, row, col, get_CODE(&tmp_Grk_W_code, col, row));
            }
        }
        matrix_matXvec_CODE(&tmp_W_Gkr_Vr_code, &tmp_W_Gkr_code, &Vr_code);
        matrix_matXvec_CODE(&tmp_W_Ihisk_code, &W_code, &Ihisk_code);
        matrix_add_CODE(&tmp_Vk_sum_code, &tmp_W_Gkr_Vr_code, &tmp_W_Ihisk_code);
        matrix_scalarMult_CODE(&Vk_code, &tmp_Vk_sum_code, -1.0);
        break;
    }
    }

    /* One variable per eliminated node, in effective k order. */
    a = get_CODE(&Vk_code, 0, 0);
    b = get_CODE(&Vk_code, 1, 0);
    c = get_CODE(&Vk_code, 2, 0);

